CREATE TABLE `institution_student_absence_details_archived` (
  `student_id` int NOT NULL COMMENT 'links to security_users.id',
  `institution_id` int NOT NULL COMMENT 'links to institutions.id',
  `academic_period_id` int NOT NULL COMMENT 'links to academic_periods.id',
  `institution_class_id` int NOT NULL COMMENT 'links to institution_classes.id',
  `education_grade_id` int NOT NULL DEFAULT '0',
  `date` date NOT NULL,
  `period` int NOT NULL,
  `comment` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci,
  `absence_type_id` int NOT NULL COMMENT 'links to student_absence_reasons.id',
  `student_absence_reason_id` int DEFAULT NULL COMMENT 'links to absence_types.id',
  `subject_id` int NOT NULL DEFAULT '0',
  `modified_user_id` int DEFAULT NULL,
  `modified` datetime DEFAULT NULL,
  `created_user_id` int NOT NULL,
  `created` datetime NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

