  `id` int NOT NULL,
  `start_date` date NOT NULL,
  `end_date` date NOT NULL,
  `student_id` int NOT NULL COMMENT 'links to security_users.id',
  `status_id` int NOT NULL COMMENT 'links to workflow_steps.id',
  `assignee_id` int NOT NULL COMMENT 'links to security_users.id',
  `institution_id` int NOT NULL COMMENT 'links to institutions.id',
  `academic_period_id` int NOT NULL COMMENT 'links to academic_periods.id',
  `education_grade_id` int NOT NULL COMMENT 'links to education_grades.id',
  `institution_class_id` int DEFAULT NULL COMMENT 'links to institution_classes.id',
  `test_score` int DEFAULT NULL,
  `interview_score` int DEFAULT NULL,
  `comment` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `modified_user_id` int DEFAULT NULL COMMENT 'links to security_users.id',
  `modified` datetime DEFAULT NULL,
  `created_user_id` int NOT NULL COMMENT 'links to security_users.id',
  `created` datetime NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

