(4, 'data_dictionary_insert', 'INSERT INTO `data_dictionary` SELECT `TABLES`.`table_schema` AS `database_name`, `TABLES`.`TABLE_NAME` AS `table_name`, `TABLES`.`TABLE_COMMENT` AS `table_description`, GROUP_CONCAT(IF(`COLUMNS`.`COLUMN_KEY` LIKE \"PRI\",`COLUMNS`.`COLUMN_NAME`,NULL)) AS `primary_keys`, GROUP_CONCAT(IF(SUBSTRING(`COLUMNS`.`COLUMN_COMMENT`,1,4) LIKE \"link\",`COLUMNS`.`COLUMN_NAME`, NULL)) AS `foreign_keys`, GROUP_CONCAT(IF(SUBSTRING(`COLUMNS`.`COLUMN_COMMENT`,1,4) LIKE \"link\",`COLUMNS`.`COLUMN_COMMENT`,NULL)) AS `linked_tables`, CURRENT_TIMESTAMP `created` FROM `information_schema`.`COLUMNS` INNER JOIN `information_schema`.`TABLES` ON `TABLES`.`table_schema` = `COLUMNS`.`TABLE_SCHEMA` AND `TABLES`.`TABLE_NAME` = `COLUMNS`.`TABLE_NAME` WHERE(`COLUMNS`.`TABLE_SCHEMA` = \"prd_cor_dmo\" OR `COLUMNS`.`TABLE_SCHEMA` = \"tst_cor_dmo\" OR `COLUMNS`.`TABLE_SCHEMA` = \"openemis_core\") AND `TABLES`.`TABLE_NAME` NOT LIKE \"z_%\" GROUP BY `COLUMNS`.`TABLE_NAME`', 'week', 1, NULL, NULL, 1, '2022-03-07 14:33:25'),
