(14, 'summary_institution_student_absences_insert', ' INSERT INTO summary_institution_student_absences SELECT institution_students.institution_id, institutions.code institution_code, institutions.name institution_name, areas.id area_id, areas.code area_code, areas.name area_name, area_administratives.id area_administrative_id, area_administratives.code area_administrative_code, area_administratives.name area_administrative_name, institution_students.student_id, security_users.openemis_no, get_student_default_identity.number default_identity_number, IF(security_users.middle_name IS NOT NULL AND security_users.third_name IS NOT NULL, CONCAT(security_users.first_name,char(32),security_users.middle_name,char(32),security_users.third_name,char(32),security_users.last_name), IF(security_users.middle_name IS NULL AND security_users.third_name IS NULL, CONCAT(security_users.first_name,char(32),security_users.last_name), IF(security_users.middle_name IS NULL AND security_users.third_name IS NOT NULL, CONCAT(security_users.first_name,char(32),security_users.third_name,char(32),security_users.last_name), CONCAT(security_users.first_name,char(32),security_users.middle_name,char(32),security_users.last_name)))) student_name, institution_students.start_date enrol_start_date, institution_students.end_date enrol_end_date, institution_students.academic_period_id, academic_periods.code academic_period_code, academic_periods.name academic_period_name, institution_student_absence_details.education_grade_id, education_grades.code education_grade_code, education_grades.name education_grade_name, institution_student_absence_details.date absent_date, institution_student_absence_days.absent_days, IF(institution_student_absence_details.subject_id = 0,IF(get_period_data.period_name IS NULL,CONCAT(char(80),char(101),char(114),char(105),char(111),char(100),char(32),char(49)), get_period_data.period_name),institution_subjects.name) absence_subject_period, institution_student_absence_details.absence_type_id, absence_types.name absence_type, institution_student_absence_details.student_absence_reason_id, student_absence_reasons.name student_absence_reasons, institution_students.student_status_id, student_statuses.name student_status, NOW() created FROM institution_students INNER JOIN student_statuses ON student_statuses.id = institution_students.student_status_id INNER JOIN institution_student_absence_details ON institution_students.student_id = institution_student_absence_details.student_id AND institution_students.institution_id = institution_student_absence_details.institution_id AND institution_students.education_grade_id = institution_student_absence_details.education_grade_id AND institution_students.academic_period_id = institution_student_absence_details.academic_period_id AND institution_student_absence_details.date BETWEEN institution_students.start_date AND institution_students.end_date INNER JOIN institution_student_absence_days ON institution_student_absence_days.student_id = institution_student_absence_details.student_id AND institution_student_absence_days.institution_id = institution_student_absence_details.institution_id AND institution_student_absence_details.date BETWEEN institution_student_absence_days.start_date AND institution_student_absence_days.end_date INNER JOIN academic_periods ON academic_periods.id = institution_student_absence_details.academic_period_id INNER JOIN institutions ON institutions.id = institution_students.institution_id INNER JOIN security_users ON security_users.id = institution_students.student_id INNER JOIN education_grades ON education_grades.id = institution_students.education_grade_id INNER JOIN absence_types ON absence_types.id = institution_student_absence_details.absence_type_id LEFT JOIN student_absence_reasons ON student_absence_reasons.id = institution_student_absence_details.student_absence_reason_id INNER JOIN areas ON areas.id = institutions.area_id LEFT JOIN area_administratives ON area_administratives.id = institutions.area_administrative_id LEFT JOIN(SELECT student_mark_type_status_grades.education_grade_id, student_mark_type_statuses.academic_period_id, student_mark_type_statuses.date_enabled, student_mark_type_statuses.date_disabled, period period_number, student_attendance_per_day_periods.name period_name FROM student_attendance_mark_types INNER JOIN student_attendance_per_day_periods ON student_attendance_per_day_periods.student_attendance_mark_type_id = student_attendance_mark_types.id INNER JOIN student_mark_type_statuses ON student_mark_type_statuses.student_attendance_mark_type_id = student_attendance_mark_types.id INNER JOIN student_mark_type_status_grades ON student_mark_type_status_grades.student_mark_type_status_id = student_mark_type_statuses.id) get_period_data ON get_period_data.academic_period_id = institution_student_absence_details.academic_period_id AND get_period_data.education_grade_id = institution_student_absence_details.education_grade_id AND institution_student_absence_details.date BETWEEN get_period_data.date_enabled AND get_period_data.date_disabled LEFT JOIN institution_subjects ON institution_subjects.id = institution_student_absence_details.subject_id LEFT JOIN (SELECT user_identities.number, user_identities.security_user_id FROM user_identities INNER JOIN identity_types ON identity_types.id = user_identities.identity_type_id WHERE identity_types.default = 1) get_student_default_identity ON get_student_default_identity.security_user_id = institution_student_absence_details.student_id ORDER BY institution_student_absence_details.student_id ASC, institution_students.academic_period_id ASC;', 'day', 0, NULL, NULL, 1, '2022-06-13 07:04:27'),
(15, 'get_total_student_subjects_create', 'CREATE TABLE IF NOT EXISTS `get_total_student_subjects`( `academic_period_id` INT(10) NOT NULL, `institution_id` INT(10) NOT NULL, `education_grade_id` INT(10) NOT NULL, `institution_class_id` INT(10) NOT NULL, `education_subject_id` INT(10) NOT NULL, `count_students` INT(10) NOT NULL, INDEX(`academic_period_id`, `institution_id`, `education_grade_id`, `education_subject_id`)) ENGINE = InnoDB DEFAULT CHARSET=utf8;', 'week', 1, NULL, NULL, 1, '2022-07-30 06:59:13'),
(16, 'get_total_student_subjects_insert', 'INSERT INTO get_total_student_subjects SELECT institution_subject_students.academic_period_id, institution_subject_students.institution_id, institution_subject_students.education_grade_id, institution_class_students.institution_class_id, institution_subject_students.education_subject_id, count(*) AS count_students FROM institution_subject_students INNER JOIN academic_periods ON academic_periods.id = academic_period_id INNER JOIN institution_students ON institution_students.student_id = institution_subject_students.student_id AND institution_students.education_grade_id = institution_subject_students.education_grade_id AND institution_students.academic_period_id = institution_subject_students.academic_period_id AND institution_students.student_status_id = institution_subject_students.student_status_id AND institution_students.institution_id = institution_subject_students.institution_id INNER JOIN institution_class_students ON institution_students.student_id = institution_class_students.student_id AND institution_students.education_grade_id = institution_class_students.education_grade_id AND institution_students.academic_period_id = institution_class_students.academic_period_id AND institution_students.student_status_id = institution_class_students.student_status_id AND institution_students.institution_id = institution_class_students.institution_id WHERE institution_students.student_status_id = 1 AND academic_periods.current = 1 GROUP BY institution_subject_students.academic_period_id, institution_subject_students.institution_id, institution_subject_students.education_grade_id, institution_class_students.institution_class_id, institution_subject_students.education_subject_id;', 'week', 1, NULL, NULL, 1, '2022-07-30 06:59:13'),
(17, 'get_grouped_students_subjects_create', 'CREATE TABLE IF NOT EXISTS `get_grouped_students_subjects`( `student_id` int(10) NOT NULL, `institution_id` int(10) NOT NULL, `academic_period_id` int(10) NOT NULL, `institution_class_id` int(10) NOT NULL, `education_subject_id` int(10) NOT NULL, `assessment_id` int(10) NOT NULL, `assessment_period_id` int(10) NOT NULL, `academic_term` varchar(100) DEFAULT NULL, INDEX(`student_id`, `institution_id`, `institution_class_id`, `academic_period_id`, `education_subject_id`, `assessment_id`, `assessment_period_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8;', 'week', 1, NULL, NULL, 1, '2022-07-30 06:59:13'),
(18, 'get_grouped_students_subjects_insert', 'INSERT INTO get_grouped_students_subjects SELECT assessment_item_results.student_id, assessment_item_results.institution_id, assessment_item_results.academic_period_id, institution_class_id, education_subject_id, assessment_item_results.assessment_id, assessment_period_id, academic_term FROM assessment_item_results INNER JOIN assessment_periods ON assessment_periods.assessment_id = assessment_item_results.assessment_id INNER JOIN academic_periods ON academic_periods.id = assessment_item_results.academic_period_id INNER JOIN institution_students ON institution_students.student_id = assessment_item_results.student_id AND institution_students.education_grade_id = assessment_item_results.education_grade_id AND institution_students.academic_period_id = assessment_item_results.academic_period_id AND institution_students.institution_id = assessment_item_results.institution_id INNER JOIN institution_class_students ON institution_students.student_id = institution_class_students.student_id AND institution_students.education_grade_id = institution_class_students.education_grade_id AND institution_students.academic_period_id = institution_class_students.academic_period_id AND institution_students.student_status_id = institution_class_students.student_status_id AND institution_students.institution_id = institution_class_students.institution_id WHERE assessment_item_results.marks IS NOT NULL AND institution_students.student_status_id = 1 AND academic_periods.current = 1 GROUP BY assessment_item_results.student_id, assessment_item_results.institution_id, assessment_item_results.academic_period_id, assessment_item_results.assessment_id, assessment_item_results.education_grade_id, institution_class_id, assessment_item_results.assessment_period_id, education_subject_id;', 'week', 1, NULL, NULL, 1, '2022-07-30 06:59:13'),
(19, 'get_marked_students_create', 'CREATE TABLE IF NOT EXISTS `get_marked_students` ( `academic_period_id` int(10) NOT NULL, `assessment_id` int(10) NOT NULL, `assessment_period_id` int(10) NOT NULL, `academic_term` varchar(100) DEFAULT NULL, `institution_id` int(10) NOT NULL, `institution_class_id` int(10) NOT NULL, `education_subject_id` int(10) NOT NULL, `count_marked_students` int(10) NOT NULL, INDEX(`academic_period_id`, `assessment_id`, `assessment_period_id`, `institution_id`, `education_subject_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8;', 'week', 1, NULL, NULL, 1, '2022-07-30 06:59:13'),
(20, 'get_marked_students_insert', 'INSERT INTO get_marked_students SELECT academic_period_id, assessment_id, assessment_period_id, academic_term, institution_id, institution_class_id, education_subject_id, count(*) count_marked_students FROM get_grouped_students_subjects GROUP BY institution_id, academic_period_id, assessment_period_id, institution_class_id, education_subject_id;', 'week', 1, NULL, NULL, 1, '2022-07-30 06:59:13'),
(21, 'summary_assessment_item_results_truncate', 'TRUNCATE summary_assessment_item_results;', 'week', 1, NULL, NULL, 1, '2022-07-30 06:59:13'),
(22, 'summary_assessment_item_results_insert', 'INSERT INTO summary_assessment_item_results SELECT academic_periods.id academic_period_id, academic_periods.name academic_period_name, get_assessments.assessment_id, assessment_code, assessment_name, assessment_periods.id assessment_period_id, assessment_periods.name assessment_period_name, get_assessments.academic_term, subject_id, subject_name, education_grades.id education_grade_id, education_grades.name education_grade, institutions.id institution_id, institutions.code institution_code, institutions.name institution_name, institution_providers.id institution_provider_id, institution_providers.name institution_provider, area_edu.area_id area_id, area_edu.area_name area, get_total_student_subjects.institution_class_id, institution_classes.name institution_class_name, IF(count_students IS NULL,0,count_students) count_students, IF(count_marked_students IS NULL,0,count_marked_students) count_marked_students, IF(count_students IS NULL,0, IF(count_marked_students IS NULL, count_students, count_students-count_marked_students)) missing_marks, CURRENT_TIMESTAMP FROM (SELECT assessments.id assessment_id, assessments.code assessment_code, assessments.name assessment_name, assessments.academic_period_id, assessments.education_grade_id, assessment_periods.id assessment_period_id, assessment_periods.academic_term, education_subjects.id subject_id, education_subjects.code subject_code, education_subjects.name subject_name FROM assessments INNER JOIN assessment_periods ON assessments.id = assessment_periods.assessment_id INNER JOIN assessment_items ON assessment_items.assessment_id = assessments.id INNER JOIN education_subjects ON assessment_items.education_subject_id = education_subjects.id) get_assessments LEFT JOIN assessment_periods ON assessment_periods.id = get_assessments.assessment_period_id INNER JOIN academic_periods ON academic_periods.id = get_assessments.academic_period_id LEFT JOIN institution_grades ON institution_grades.education_grade_id = get_assessments.education_grade_id INNER JOIN institutions ON institutions.id = institution_grades.institution_id INNER JOIN institution_providers ON institution_providers.id = institutions.institution_provider_id LEFT JOIN (SELECT areas.id AS area_id, areas.name AS area_name FROM areas INNER JOIN area_levels ON area_levels.id = areas.area_level_id) AS area_edu ON institutions.area_id = area_edu.area_id INNER JOIN education_grades ON education_grades.id = get_assessments.education_grade_id LEFT JOIN get_total_student_subjects ON get_total_student_subjects.institution_id = institutions.id AND get_total_student_subjects.academic_period_id = get_assessments.academic_period_id AND get_total_student_subjects.education_grade_id = get_assessments.education_grade_id AND get_total_student_subjects.education_subject_id = get_assessments.subject_id LEFT JOIN get_marked_students ON get_marked_students.institution_id = institutions.id AND get_marked_students.assessment_id = get_assessments.assessment_id AND get_marked_students.assessment_period_id = assessment_periods.id AND get_marked_students.academic_period_id = academic_periods.id AND get_marked_students.education_subject_id = get_assessments.subject_id AND get_marked_students.institution_class_id=get_total_student_subjects.institution_class_id LEFT JOIN institution_classes ON institution_classes.id = get_total_student_subjects.institution_class_id WHERE area_edu.area_id IS NOT NULL AND institutions.id IS NOT NULL AND education_grades.id IS NOT NULL AND get_assessments.assessment_id IS NOT NULL AND assessment_periods.id IS NOT NULL AND academic_periods.current = 1 ORDER BY academic_periods.id ASC, institutions.id ASC, assessment_periods.id ASC;', 'week', 1, NULL, NULL, 1, '2022-07-30 06:59:13'),
