(24, 'system_errors_truncate', 'TRUNCATE system_errors;', 'week', 1, NULL, NULL, 1, '2022-08-09 10:26:20'),
(25, 'report_student_assessment_summary_insert', 'INSERT INTO report_student_assessment_summary SELECT academic_periods.id academic_period_id ,academic_periods.code academic_period_code ,academic_periods.name academic_period_name ,areas.id area_id ,areas.code area_code ,areas.name area_name ,institutions.id institution_id ,institutions.code institution_code ,institutions.name institution_name ,education_grades.id education_grade_id ,education_grades.code education_grade_code ,education_grades.name education_grade_name ,institution_classes.id institution_class_id ,institution_classes.name institution_class_name ,homeroom_teacher.id homeroom_teacher_id ,CONCAT(homeroom_teacher.first_name,homeroom_teacher.last_name) homeroom_teacher_name ,education_subjects.id education_subject_id ,education_subjects.code education_subject_code ,education_subjects.name education_subject_name ,assessment_items.weight subject_weight ,assessments.id assessment_id ,assessments.code assessment_code ,assessments.name assessment_name ,assessment_periods.id assessment_period_id ,assessment_periods.code assessment_period_code ,assessment_periods.name assessment_period_name ,assessment_periods.academic_term ,assessment_periods.weight period_weight ,students.id student_id ,CONCAT(students.first_name,students.last_name) student_name ,assessment_item_results.marks latest_mark ,get_total_student_mark.total_mark ,get_avg_student_mark.average_mark ,get_instituion_average_mark.instituion_average_mark ,get_area_average_mark.area_average_mark ,NOW() created FROM assessment_item_results INNER JOIN institutions ON institutions.id = assessment_item_results.institution_id INNER JOIN areas ON areas.id = institutions.area_id INNER JOIN education_grades ON education_grades.id = assessment_item_results.education_grade_id LEFT JOIN institution_classes ON institution_classes.id = assessment_item_results.institution_classes_id AND institution_classes.institution_id = institutions.id INNER JOIN education_subjects ON education_subjects.id = assessment_item_results.education_subject_id INNER JOIN assessments ON assessments.id = assessment_item_results.assessment_id AND assessments.academic_period_id = assessment_item_results.academic_period_id AND assessments.education_grade_id = assessment_item_results.education_grade_id INNER JOIN assessment_items ON assessment_items.assessment_id = assessments.id AND assessment_items.education_subject_id = assessment_item_results.education_subject_id INNER JOIN assessment_periods ON assessment_periods.id = assessment_item_results.assessment_period_id INNER JOIN security_users students ON students.id = assessment_item_results.student_id LEFT JOIN security_users homeroom_teacher ON institution_classes.staff_id = homeroom_teacher.id INNER JOIN( SELECT assessment_item_results.student_id ,assessment_item_results.assessment_period_id ,assessment_item_results.education_subject_id ,MAX(assessment_item_results.created) latest_created FROM assessment_item_results GROUP BY assessment_item_results.student_id ,assessment_item_results.assessment_period_id ,assessment_item_results.education_subject_id) latest_data ON latest_data.student_id = assessment_item_results.student_id AND latest_data.assessment_period_id = assessment_item_results.assessment_period_id AND latest_data.education_subject_id = assessment_item_results.education_subject_id AND latest_data.latest_created = assessment_item_results.created INNER JOIN academic_periods ON academic_periods.id = assessment_item_results.academic_period_id LEFT JOIN ( SELECT institution_subject_students.academic_period_id ,institution_subject_students.institution_id ,institution_subject_students.institution_class_id ,institution_subject_students.education_grade_id ,institution_subject_students.student_id ,institution_subject_students.education_subject_id ,ROUND(AVG(institution_subject_students.total_mark),2) total_mark FROM institution_subject_students GROUP BY institution_subject_students.academic_period_id ,institution_subject_students.institution_id ,institution_subject_students.institution_class_id ,institution_subject_students.education_grade_id ,institution_subject_students.student_id ,institution_subject_students.education_subject_id ) get_total_student_mark ON get_total_student_mark.academic_period_id = assessment_item_results.academic_period_id AND get_total_student_mark.institution_id = assessment_item_results.institution_id AND get_total_student_mark.institution_class_id = assessment_item_results.institution_classes_id AND get_total_student_mark.education_grade_id = assessment_item_results.education_grade_id AND get_total_student_mark.student_id = assessment_item_results.student_id AND get_total_student_mark.education_subject_id = assessment_item_results.education_subject_id LEFT JOIN ( SELECT institution_subject_students.academic_period_id ,institution_subject_students.institution_id ,institution_subject_students.institution_class_id ,institution_subject_students.education_grade_id ,institution_subject_students.student_id ,ROUND(AVG(institution_subject_students.total_mark),2) average_mark FROM institution_subject_students GROUP BY institution_subject_students.academic_period_id ,institution_subject_students.institution_id ,institution_subject_students.institution_class_id ,institution_subject_students.education_grade_id ,institution_subject_students.student_id ) get_avg_student_mark ON get_avg_student_mark.academic_period_id = assessment_item_results.academic_period_id AND get_avg_student_mark.institution_id = assessment_item_results.institution_id AND get_avg_student_mark.institution_class_id = assessment_item_results.institution_classes_id AND get_avg_student_mark.education_grade_id = assessment_item_results.education_grade_id AND get_avg_student_mark.student_id = assessment_item_results.student_id LEFT JOIN ( SELECT institution_subject_students.academic_period_id ,institution_subject_students.institution_id ,ROUND(AVG(institution_subject_students.total_mark),2) instituion_average_mark FROM institution_subject_students GROUP BY institution_subject_students.academic_period_id ,institution_subject_students.institution_id ) get_instituion_average_mark ON get_instituion_average_mark.academic_period_id = assessment_item_results.academic_period_id AND get_instituion_average_mark.institution_id = assessment_item_results.institution_id LEFT JOIN ( SELECT institution_subject_students.academic_period_id ,institutions.area_id ,ROUND(AVG(institution_subject_students.total_mark),2) area_average_mark FROM institution_subject_students INNER JOIN institutions ON institutions.id = institution_subject_students.institution_id GROUP BY institution_subject_students.academic_period_id ,institutions.area_id ) get_area_average_mark ON get_area_average_mark.academic_period_id = assessment_item_results.academic_period_id AND get_area_average_mark.area_id = areas.id', 'week', 1, NULL, NULL, 1, '2022-11-01 01:09:25'),
(26, 'summary_institutions_truncate', 'TRUNCATE summary_institutions;', 'week', 1, NULL, NULL, 1, '2022-11-21 07:22:05'),
(27, 'summary_institutions_insert', 'INSERT INTO summary_institutions (academic_period_id, academic_period_name, institution_id, institution_code, total_grades, total_classes, total_lands, total_land_size, total_buildings, total_building_sizes, total_floors, total_floor_sizes, total_rooms, total_room_sizes, total_room_classrooms, total_room_classroom_sizes, total_students, total_students_female, total_students_male, total_staff_teaching, total_staff_teaching_female, total_staff_teaching_male, total_staff_non_teaching, total_staff_non_teaching_female, total_staff_non_teaching_male) SELECT academic_periods.id academic_period_id ,academic_periods.name academic_period_name ,institutions.id institution_id ,institutions.code institution_code ,IFNULL(grade_count.total_grades, 0) total_grades ,IFNULL(class_count.total_classes, 0) total_classes ,IFNULL(land_info.total_lands, 0) total_lands ,IFNULL(land_info.total_land_size, 0) total_land_size ,IFNULL(building_info.total_buildings, 0) total_buildings ,IFNULL(building_info.total_building_sizes, 0) total_building_sizes ,IFNULL(floor_info.total_floors, 0) total_floors ,IFNULL(floor_info.total_floor_sizes, 0) total_floor_sizes ,IFNULL(room_info.total_rooms, 0) total_rooms ,IFNULL(room_info.total_room_sizes, 0) total_room_sizes ,IFNULL(classroom_info.total_room_classrooms, 0) total_room_classrooms ,IFNULL(classroom_info.total_room_classroom_sizes, 0) total_room_classroom_sizes ,IFNULL(student_info.total_students, 0) total_students ,IFNULL(student_info.total_students_female, 0) total_students_female ,IFNULL(student_info.total_students_male, 0) total_students_male ,IFNULL(teaching_staff_info.total_staff_teaching, 0) total_staff_teaching ,IFNULL(teaching_staff_info.total_staff_teaching_female, 0) total_staff_teaching_female ,IFNULL(teaching_staff_info.total_staff_teaching_male, 0) total_staff_teaching_male ,IFNULL(non_teaching_staff_info.total_staff_non_teaching, 0) total_staff_non_teaching ,IFNULL(non_teaching_staff_info.total_staff_non_teaching_female, 0) total_staff_non_teaching_female ,IFNULL(non_teaching_staff_info.total_staff_non_teaching_male, 0) total_staff_non_teaching_male FROM institutions INNER JOIN academic_periods ON (((institutions.date_closed IS NOT NULL AND institutions.date_opened <= academic_periods.start_date AND institutions.date_closed >= academic_periods.start_date) OR (institutions.date_closed IS NOT NULL AND institutions.date_opened <= academic_periods.end_date AND institutions.date_closed >= academic_periods.end_date) OR (institutions.date_closed IS NOT NULL AND institutions.date_opened >= academic_periods.start_date AND institutions.date_closed <= academic_periods.end_date)) OR (institutions.date_closed IS NULL AND institutions.date_opened <= academic_periods.end_date)) LEFT JOIN ( SELECT academic_periods.id academic_period_id ,institution_grades.institution_id ,COUNT(DISTINCT(education_grades.id)) total_grades FROM institution_grades INNER JOIN education_grades ON education_grades.id = institution_grades.education_grade_id INNER JOIN institutions ON institutions.id = institution_grades.institution_id INNER JOIN education_programmes ON education_programmes.id = education_grades.education_programme_id INNER JOIN education_cycles ON education_cycles.id = education_programmes.education_cycle_id INNER JOIN education_levels ON education_levels.id = education_cycles.education_level_id INNER JOIN education_systems ON education_systems.id = education_levels.education_system_id INNER JOIN academic_periods ON academic_periods.id = education_systems.academic_period_id GROUP BY institution_grades.institution_id ,academic_periods.id) grade_count ON grade_count.institution_id = institutions.id AND grade_count.academic_period_id = academic_periods.id LEFT JOIN ( SELECT institution_classes.academic_period_id ,institution_classes.institution_id ,COUNT(DISTINCT(institution_classes.id)) total_classes FROM institution_classes GROUP BY institution_classes.institution_id ,institution_classes.academic_period_id ) class_count ON class_count.institution_id = institutions.id AND class_count.academic_period_id = academic_periods.id LEFT JOIN ( SELECT institution_lands.academic_period_id ,institution_lands.institution_id ,COUNT(DISTINCT(institution_lands.id)) total_lands ,SUM(IFNULL(institution_lands.area, 0)) total_land_size FROM institution_lands GROUP BY institution_lands.institution_id ,institution_lands.academic_period_id ) land_info ON land_info.institution_id = institutions.id AND land_info.academic_period_id = academic_periods.id LEFT JOIN ( SELECT institution_buildings.academic_period_id ,institution_buildings.institution_id ,COUNT(DISTINCT(institution_buildings.id)) total_buildings ,SUM(IFNULL(institution_buildings.area, 0)) total_building_sizes FROM institution_buildings GROUP BY institution_buildings.institution_id ,institution_buildings.academic_period_id ) building_info ON building_info.institution_id = institutions.id AND building_info.academic_period_id = academic_periods.id LEFT JOIN ( SELECT institution_floors.academic_period_id ,institution_floors.institution_id ,COUNT(DISTINCT(institution_floors.id)) total_floors ,SUM(IFNULL(institution_floors.area, 0)) total_floor_sizes FROM institution_floors GROUP BY institution_floors.institution_id ,institution_floors.academic_period_id ) floor_info ON floor_info.institution_id = institutions.id AND floor_info.academic_period_id = academic_periods.id LEFT JOIN ( SELECT institution_rooms.academic_period_id ,institution_rooms.institution_id ,COUNT(DISTINCT(institution_rooms.id)) total_rooms ,SUM(IFNULL(institution_rooms.area, 0)) total_room_sizes FROM institution_rooms GROUP BY institution_rooms.institution_id ,institution_rooms.academic_period_id ) room_info ON room_info.institution_id = institutions.id AND room_info.academic_period_id = academic_periods.id LEFT JOIN ( SELECT institution_rooms.academic_period_id ,institution_rooms.institution_id ,COUNT(DISTINCT(institution_rooms.id)) total_room_classrooms ,SUM(IFNULL(institution_rooms.area, 0)) total_room_classroom_sizes FROM institution_rooms INNER JOIN room_types ON room_types.id = institution_rooms.room_type_id WHERE room_types.classification = 1 GROUP BY institution_rooms.institution_id ,institution_rooms.academic_period_id ) classroom_info ON classroom_info.institution_id = institutions.id AND classroom_info.academic_period_id = academic_periods.id LEFT JOIN ( SELECT institution_students.academic_period_id ,institution_students.institution_id ,SUM(CASE WHEN security_users.gender_id IN (1, 2) THEN 1 ELSE 0 END) total_students ,SUM(CASE WHEN security_users.gender_id = 2 THEN 1 ELSE 0 END) total_students_female ,SUM(CASE WHEN security_users.gender_id = 1 THEN 1 ELSE 0 END) total_students_male FROM institution_students INNER JOIN security_users ON security_users.id = institution_students.student_id INNER JOIN academic_periods ON academic_periods.id = institution_students.academic_period_id WHERE IF((CURRENT_DATE >= academic_periods.start_date AND CURRENT_DATE <= academic_periods.end_date), institution_students.student_status_id = 1, institution_students.student_status_id IN (1, 7, 6, 8)) GROUP BY institution_students.institution_id ,institution_students.academic_period_id ) student_info ON student_info.institution_id = institutions.id AND student_info.academic_period_id = academic_periods.id LEFT JOIN ( SELECT academic_periods.id academic_period_id ,institution_staff.institution_id ,SUM(CASE WHEN security_users.gender_id IN (1, 2) THEN 1 ELSE 0 END) total_staff_teaching ,SUM(CASE WHEN security_users.gender_id = 2 THEN 1 ELSE 0 END) total_staff_teaching_female ,SUM(CASE WHEN security_users.gender_id = 1 THEN 1 ELSE 0 END) total_staff_teaching_male FROM institution_staff INNER JOIN security_users ON security_users.id = institution_staff.staff_id INNER JOIN institution_positions ON institution_positions.id = institution_staff.institution_position_id AND institution_positions.institution_id = institution_staff.institution_id INNER JOIN staff_position_titles ON staff_position_titles.id = institution_positions.staff_position_title_id INNER JOIN academic_periods ON (((institution_staff.end_date IS NOT NULL AND institution_staff.start_date <= academic_periods.start_date AND institution_staff.end_date >= academic_periods.start_date) OR (institution_staff.end_date IS NOT NULL AND institution_staff.start_date <= academic_periods.end_date AND institution_staff.end_date >= academic_periods.end_date) OR (institution_staff.end_date IS NOT NULL AND institution_staff.start_date >= academic_periods.start_date AND institution_staff.end_date <= academic_periods.end_date)) OR (institution_staff.end_date IS NULL AND institution_staff.start_date <= academic_periods.end_date)) WHERE institution_staff.staff_status_id = 1 AND staff_position_titles.type = 1 GROUP BY institution_staff.institution_id ,academic_periods.id ) teaching_staff_info ON teaching_staff_info.institution_id = institutions.id AND teaching_staff_info.academic_period_id = academic_periods.id LEFT JOIN ( SELECT academic_periods.id academic_period_id ,institution_staff.institution_id ,SUM(CASE WHEN security_users.gender_id IN (1, 2) THEN 1 ELSE 0 END) total_staff_non_teaching ,SUM(CASE WHEN security_users.gender_id = 2 THEN 1 ELSE 0 END) total_staff_non_teaching_female ,SUM(CASE WHEN security_users.gender_id = 1 THEN 1 ELSE 0 END) total_staff_non_teaching_male FROM institution_staff INNER JOIN security_users ON security_users.id = institution_staff.staff_id INNER JOIN institution_positions ON institution_positions.id = institution_staff.institution_position_id AND institution_positions.institution_id = institution_staff.institution_id INNER JOIN staff_position_titles ON staff_position_titles.id = institution_positions.staff_position_title_id INNER JOIN academic_periods ON (((institution_staff.end_date IS NOT NULL AND institution_staff.start_date <= academic_periods.start_date AND institution_staff.end_date >= academic_periods.start_date) OR (institution_staff.end_date IS NOT NULL AND institution_staff.start_date <= academic_periods.end_date AND institution_staff.end_date >= academic_periods.end_date) OR (institution_staff.end_date IS NOT NULL AND institution_staff.start_date >= academic_periods.start_date AND institution_staff.end_date <= academic_periods.end_date)) OR (institution_staff.end_date IS NULL AND institution_staff.start_date <= academic_periods.end_date)) WHERE institution_staff.staff_status_id = 1 AND staff_position_titles.type = 0 GROUP BY institution_staff.institution_id ,academic_periods.id ) non_teaching_staff_info ON non_teaching_staff_info.institution_id = institutions.id AND non_teaching_staff_info.academic_period_id = academic_periods.id;', 'week', 1, NULL, NULL, 1, '2022-11-21 07:22:05'),
(28, 'summary_institution_grades_truncate', 'TRUNCATE summary_institution_grades;', 'week', 1, NULL, NULL, 1, '2022-11-21 07:22:05'),
(29, 'summary_institution_grades_insert', 'INSERT INTO summary_institution_grades (academic_period_id, academic_period_name, institution_id, institution_code, grade_id, grade_name, total_classes, total_classes_female, total_classes_male, total_classes_mixed, total_students, total_students_female, total_students_male, total_home_room_teachers, total_secondary_teachers) SELECT academic_periods.id academic_period_id ,academic_periods.name academic_period_name ,institutions.id institution_id ,institutions.code institution_code ,education_grades.id grade_id ,education_grades.name grade_name ,IFNULL(SUM(classes_info.total_classes), 0) total_classes ,IFNULL(SUM(classes_info.female_classes), 0) total_classes_female ,IFNULL(SUM(classes_info.male_classes), 0) total_classes_male ,IFNULL(SUM(classes_info.mixed_classes), 0) total_classes_mixed ,IFNULL(SUM(student_info.total_students), 0) total_students ,IFNULL(SUM(student_info.total_students_female), 0) total_students_female ,IFNULL(SUM(student_info.total_students_male), 0) total_students_male ,IFNULL(SUM(classes_info.total_home_room_teachers), 0) total_home_room_teachers ,IFNULL(SUM(classes_info.total_secondary_teachers), 0) total_secondary_teachers FROM institution_grades INNER JOIN education_grades ON education_grades.id = institution_grades.education_grade_id INNER JOIN institutions ON institutions.id = institution_grades.institution_id INNER JOIN education_programmes ON education_programmes.id = education_grades.education_programme_id INNER JOIN education_cycles ON education_cycles.id = education_programmes.education_cycle_id INNER JOIN education_levels ON education_levels.id = education_cycles.education_level_id INNER JOIN education_systems ON education_systems.id = education_levels.education_system_id INNER JOIN academic_periods ON academic_periods.id = education_systems.academic_period_id LEFT JOIN ( SELECT academic_periods.id academic_period_id ,institution_classes.institution_id ,education_grades.id education_grade_id ,SUM(CASE WHEN institution_classes.total_male_students > 0 AND institution_classes.total_female_students = 0 THEN 1 ELSE 0 END) male_classes ,SUM(CASE WHEN institution_classes.total_male_students = 0 AND institution_classes.total_female_students > 0 THEN 1 ELSE 0 END) female_classes ,SUM(CASE WHEN IF((CURRENT_DATE >= academic_periods.start_date AND CURRENT_DATE <= academic_periods.end_date), (institution_classes.total_male_students > 0 AND institution_classes.total_female_students > 0), ((institution_classes.total_male_students > 0 AND institution_classes.total_female_students > 0) OR (institution_classes.total_male_students = 0 AND institution_classes.total_female_students = 0))) THEN 1 ELSE 0 END) mixed_classes ,COUNT(institution_classes.id) total_classes ,COUNT(DISTINCT(CASE WHEN institution_classes.staff_id != 0 THEN institution_classes.staff_id END)) total_home_room_teachers ,COUNT(DISTINCT(institution_classes_secondary_staff.secondary_staff_id)) total_secondary_teachers FROM institution_class_grades INNER JOIN institution_classes ON institution_classes.id = institution_class_grades.institution_class_id INNER JOIN education_grades ON education_grades.id = institution_class_grades.education_grade_id INNER JOIN academic_periods ON academic_periods.id = institution_classes.academic_period_id LEFT JOIN institution_classes_secondary_staff ON institution_classes_secondary_staff.institution_class_id = institution_classes.id GROUP BY academic_periods.id ,institution_classes.institution_id ,institution_class_grades.education_grade_id) classes_info ON classes_info.academic_period_id = academic_periods.id AND classes_info.institution_id = institutions.id AND classes_info.education_grade_id = education_grades.id LEFT JOIN ( SELECT institution_students.academic_period_id ,institution_students.institution_id ,institution_students.education_grade_id ,SUM(CASE WHEN security_users.gender_id IN (1,2) AND IF((CURRENT_DATE >= academic_periods.start_date AND CURRENT_DATE <= academic_periods.end_date), institution_students.student_status_id = 1, institution_students.student_status_id IN (1, 7, 6, 8)) THEN 1 ELSE 0 END) total_students ,SUM(CASE WHEN security_users.gender_id = 2 AND IF((CURRENT_DATE >= academic_periods.start_date AND CURRENT_DATE <= academic_periods.end_date), institution_students.student_status_id = 1, institution_students.student_status_id IN (1, 7, 6, 8)) THEN 1 ELSE 0 END) total_students_female ,SUM(CASE WHEN security_users.gender_id = 1 AND IF((CURRENT_DATE >= academic_periods.start_date AND CURRENT_DATE <= academic_periods.end_date), institution_students.student_status_id = 1, institution_students.student_status_id IN (1, 7, 6, 8)) THEN 1 ELSE 0 END) total_students_male FROM institution_students INNER JOIN security_users ON security_users.id = institution_students.student_id INNER JOIN academic_periods ON academic_periods.id = institution_students.academic_period_id GROUP BY institution_students.academic_period_id ,institution_students.institution_id ,institution_students.education_grade_id ) student_info ON student_info.academic_period_id = academic_periods.id AND student_info.institution_id = institutions.id AND student_info.education_grade_id = education_grades.id GROUP BY academic_periods.id ,institution_grades.institution_id ,education_grades.id;', 'week', 1, NULL, NULL, 1, '2022-11-21 07:22:05'),
(30, 'summary_institution_room_types_truncate', 'TRUNCATE summary_institution_room_types;', 'week', 1, NULL, NULL, 1, '2022-11-21 07:22:05'),
(31, 'summary_institution_room_types_insert', 'INSERT INTO summary_institution_room_types (academic_period_id, academic_period_name, institution_id, institution_code, room_type, total_rooms) SELECT academic_periods.id academic_period_id ,academic_periods.name academic_period_name ,institutions.id institution_id ,institutions.code institution_code ,room_types.name room_type ,COUNT(DISTINCT(institution_rooms.id)) total_rooms FROM institution_rooms INNER JOIN room_types ON room_types.id = institution_rooms.room_type_id INNER JOIN institutions ON institutions.id = institution_rooms.institution_id INNER JOIN academic_periods ON academic_periods.id = institution_rooms.academic_period_id GROUP BY academic_periods.id ,institutions.id ,room_types.id;', 'week', 1, NULL, NULL, 1, '2022-11-21 07:22:05'),
(38, 'clear_otp', 'DELETE FROM security_user_codes WHERE created < DATE_SUB(NOW(), INTERVAL `1` HOUR);', 'hour', 1, NULL, NULL, 1, '2023-01-06 09:42:45'),
