(40, 'summary_programme_sector_genders_insert', 'INSERT INTO summary_programme_sector_genders (academic_period_id, academic_period_name, institution_sector_id, institution_sector_name, education_system_id, education_system_name, education_level_isced_id, education_level_isced_name, education_level_isced_level, education_level_id, education_level_name, education_cycle_id, education_cycle_name, education_programme_id, education_programme_code, education_programme_name, gender_id, gender_name, total_students, total_staff_teaching, total_staff_teaching_newly_recruited) SELECT subq1.academic_period_id ,subq1.academic_period_name ,subq1.institution_sector_id ,subq1.institution_sector_name ,subq1.education_system_id ,subq1.education_system_name ,subq1.education_level_isced_id ,subq1.education_level_isced_name ,subq1.education_level_isced_level ,subq1.education_level_id ,subq1.education_level_name ,subq1.education_cycle_id ,subq1.education_cycle_name ,subq1.education_programme_id ,subq1.education_programme_code ,subq1.education_programme_name ,subq1.gender_id ,subq1.gender_name ,subq1.total_students ,IFNULL(subq2.total_staff_teaching, 0) total_staff_teaching ,IFNULL(subq2.total_staff_teaching_newly_recruited, 0) total_staff_teaching_newly_recruited FROM ( SELECT academic_periods.id academic_period_id ,academic_periods.name academic_period_name ,institution_sectors.id institution_sector_id ,institution_sectors.name institution_sector_name ,education_systems.id education_system_id ,education_systems.name education_system_name ,education_level_isced.id education_level_isced_id ,education_level_isced.name education_level_isced_name ,education_level_isced.isced_level education_level_isced_level ,education_levels.id education_level_id ,education_levels.name education_level_name ,education_cycles.id education_cycle_id ,education_cycles.name education_cycle_name ,education_programmes.id education_programme_id ,education_programmes.code education_programme_code ,education_programmes.name education_programme_name ,genders.id gender_id ,genders.name gender_name ,COUNT(DISTINCT(institution_students.student_id)) total_students FROM institution_students INNER JOIN institutions ON institutions.id = institution_students.institution_id INNER JOIN institution_sectors ON institution_sectors.id = institutions.institution_sector_id INNER JOIN security_users ON security_users.id = institution_students.student_id INNER JOIN genders ON genders.id = security_users.gender_id INNER JOIN education_grades ON education_grades.id = institution_students.education_grade_id INNER JOIN education_programmes ON education_programmes.id = education_grades.education_programme_id INNER JOIN education_cycles ON education_cycles.id = education_programmes.education_cycle_id INNER JOIN education_levels ON education_levels.id = education_cycles.education_level_id INNER JOIN education_level_isced ON education_level_isced.id = education_levels.education_level_isced_id INNER JOIN education_systems ON education_systems.id = education_levels.education_system_id INNER JOIN academic_periods ON academic_periods.id = institution_students.academic_period_id WHERE institutions.institution_status_id = 1 AND IF((CURRENT_DATE >= academic_periods.start_date AND CURRENT_DATE <= academic_periods.end_date), institution_students.student_status_id = 1, institution_students.student_status_id IN (1, 7, 6, 8)) GROUP BY academic_periods.id ,institution_sectors.id ,education_level_isced.id ,education_programmes.id ,genders.id) subq1 LEFT JOIN ( SELECT subq.academic_period_id ,subq.academic_period_name ,subq.institution_sector_id ,subq.institution_sector_name ,subq.education_system_id ,subq.education_system_name ,subq.education_level_isced_id ,subq.education_level_isced_name ,subq.education_level_isced_level ,subq.education_level_id ,subq.education_level_name ,subq.education_cycle_id ,subq.education_cycle_name ,subq.education_programme_id ,subq.education_programme_code ,subq.education_programme_name ,subq.gender_id ,subq.gender_name ,COUNT(DISTINCT(subq.staff_id)) total_staff_teaching ,SUM(CASE WHEN subq.staff_start_date BETWEEN DATE_SUB(subq.academic_period_start_date,INTERVAL 12 MONTH) AND subq.academic_period_end_date THEN 1 ELSE 0 END) total_staff_teaching_newly_recruited FROM ( SELECT academic_periods.id academic_period_id ,academic_periods.name academic_period_name ,institution_sectors.id institution_sector_id ,institution_sectors.name institution_sector_name ,education_systems.id education_system_id ,education_systems.name education_system_name ,education_level_isced.id education_level_isced_id ,education_level_isced.name education_level_isced_name ,education_level_isced.isced_level education_level_isced_level ,education_levels.id education_level_id ,education_levels.name education_level_name ,education_cycles.id education_cycle_id ,education_cycles.name education_cycle_name ,education_programmes.id education_programme_id ,education_programmes.code education_programme_code ,education_programmes.name education_programme_name ,genders.id gender_id ,genders.name gender_name ,institution_subject_staff.staff_id staff_id ,staff_data.staff_start_date staff_start_date ,academic_periods.start_date academic_period_start_date ,academic_periods.end_date academic_period_end_date FROM institution_subject_staff INNER JOIN institutions ON institutions.id = institution_subject_staff.institution_id INNER JOIN institution_sectors ON institution_sectors.id = institutions.institution_sector_id INNER JOIN ( SELECT institution_staff.staff_id ,institution_staff.institution_id ,MIN(institution_staff.start_date) staff_start_date FROM institution_staff INNER JOIN institution_positions ON institution_positions.id = institution_staff.institution_position_id AND institution_positions.institution_id = institution_staff.institution_id INNER JOIN staff_position_titles ON staff_position_titles.id = institution_positions.staff_position_title_id WHERE staff_position_titles.type = 1 GROUP BY institution_staff.staff_id ,institution_staff.institution_id ) staff_data ON staff_data.staff_id = institution_subject_staff.staff_id AND staff_data.institution_id = institution_subject_staff.institution_id INNER JOIN institution_subjects ON institution_subjects.id = institution_subject_staff.institution_subject_id INNER JOIN security_users ON security_users.id = institution_subject_staff.staff_id INNER JOIN genders ON genders.id = security_users.gender_id INNER JOIN education_grades ON education_grades.id = institution_subjects.education_grade_id INNER JOIN education_programmes ON education_programmes.id = education_grades.education_programme_id INNER JOIN education_cycles ON education_cycles.id = education_programmes.education_cycle_id INNER JOIN education_levels ON education_levels.id = education_cycles.education_level_id INNER JOIN education_level_isced ON education_level_isced.id = education_levels.education_level_isced_id INNER JOIN education_systems ON education_systems.id = education_levels.education_system_id INNER JOIN academic_periods ON academic_periods.id = institution_subjects.academic_period_id GROUP BY academic_periods.id ,institution_sectors.id ,education_level_isced.id ,education_programmes.id ,genders.id ,security_users.id ) subq GROUP BY subq.academic_period_id ,subq.institution_sector_id ,subq.education_level_isced_id ,subq.education_programme_id ,subq.gender_id ) subq2 ON subq1.academic_period_id = subq2.academic_period_id AND subq1.institution_sector_id = subq2.institution_sector_id AND subq1.education_level_isced_id = subq2.education_level_isced_id AND subq1.education_programme_id = subq2.education_programme_id AND subq1.gender_id = subq2.gender_id;', 'week', 1, NULL, NULL, 1, '2023-01-12 07:54:34'),
