tion_grade_id INNER JOIN education_programmes ON education_programmes.id = education_grades.education_programme_id INNER JOIN education_cycles ON education_cycles.id = education_programmes.education_cycle_id INNER JOIN education_levels ON education_levels.id = education_cycles.education_level_id INNER JOIN education_level_isced ON education_level_isced.id = education_levels.education_level_isced_id INNER JOIN education_systems ON education_systems.id = education_levels.education_system_id INNER JOIN academic_periods ON academic_periods.id = institution_students.academic_period_id WHERE institutions.institution_status_id = 1 GROUP BY academic_periods.id ,education_level_isced.id ,education_grades.id ,genders.id ,student_statuses.id;', 'week', 1, NULL, NULL, 1, '2023-01-12 07:54:34'),
