_id ,education_levels.name education_level_name ,education_cycles.id education_cycle_id ,education_cycles.name education_cycle_name ,education_programmes.id education_programme_id ,education_programmes.code education_programme_code ,education_programmes.name education_programme_name ,genders.id staff_gender_id ,genders.name staff_gender_name ,qualification_staff.titles_ID ,qualification_staff.Title_Name ,institution_subject_staff.staff_id staff_id ,staff_data.staff_start_date staff_start_date ,academic_periods.start_date academic_period_start_date ,academic_periods.end_date academic_period_end_date FROM institution_subject_staff INNER JOIN institutions ON institutions.id = institution_subject_staff.institution_id INNER JOIN institution_sectors ON institution_sectors.id = institutions.institution_sector_id INNER JOIN ( SELECT institution_staff.staff_id ,institution_staff.institution_id ,MIN(institution_staff.start_date) staff_start_date FROM institution_staff INNER JOIN institution_positions ON institution_positions.id = institution_staff.institution_position_id AND institution_positions.institution_id = institution_staff.institution_id INNER JOIN staff_position_titles ON staff_position_titles.id = institution_positions.staff_position_title_id WHERE staff_position_titles.type = 1 GROUP BY institution_staff.staff_id ,institution_staff.institution_id) staff_data ON staff_data.staff_id = institution_subject_staff.staff_id AND staff_data.institution_id = institution_subject_staff.institution_id INNER JOIN ( SELECT staff_qualifications.staff_id staff_id ,staff_qualifications.qualification_title_id ,qualification_titles.id titles_ID ,qualification_titles.name Title_Name ,qualification_level.highest_qualification highest_qualification FROM staff_qualifications INNER JOIN qualification_titles ON qualification_titles.id = staff_qualifications.qualification_title_id INNER JOIN ( SELECT staff_qualifications.staff_id staff_id ,MAX(qualification_titles.order) highest_qualification FROM staff_qualifications INNER JOIN qualification_titles ON qualification_titles.id = staff_qualifications.qualification_title_id GROUP BY staff_qualifications.staff_id ) qualification_level ON qualification_level.staff_id = staff_qualifications.staff_id AND qualification_level.highest_qualification = qualification_titles.order GROUP BY staff_qualifications.staff_id ) AS qualification_staff ON qualification_staff.staff_id = staff_data.staff_id INNER JOIN institution_subjects ON institution_subjects.id = institution_subject_staff.institution_subject_id INNER JOIN security_users ON security_users.id = institution_subject_staff.staff_id INNER JOIN genders ON genders.id = security_users.gender_id INNER JOIN education_grades ON education_grades.id = institution_subjects.education_grade_id INNER JOIN education_programmes ON education_programmes.id = education_grades.education_programme_id INNER JOIN education_cycles ON education_cycles.id = education_programmes.education_cycle_id INNER JOIN education_levels ON education_levels.id = education_cycles.education_level_id INNER JOIN education_level_isced ON education_level_isced.id = education_levels.education_level_isced_id INNER JOIN education_systems ON education_systems.id = education_levels.education_system_id INNER JOIN academic_periods ON academic_periods.id = institution_subjects.academic_period_id GROUP BY academic_periods.id ,institution_sectors.id ,education_level_isced.id ,education_programmes.id ,genders.id ,qualification_staff.titles_ID ,security_users.id ) subq GROUP BY subq.academic_period_id ,subq.institution_sector_id ,subq.education_level_isced_id ,subq.education_programme_id ,subq.titles_ID ,subq.staff_gender_id;', 'week', 1, NULL, NULL, 1, '2023-01-12 07:54:34'),
