(50, 'summary_isced_sectors_insert', 'INSERT INTO summary_isced_sectors(academic_period_id, academic_period_name, institution_sector_id, institution_sector_name, education_system_id, education_system_name, education_level_isced_id, education_level_isced_name, education_level_isced_level, total_instiutions, total_electricity_institutions, total_computer_institutions, total_teaching_computer_institutions, total_internet_institutions, total_toilet_institutions, total_improved_toilet_institutions, total_single_sex_toilet_institutions, total_improved_single_sex_toilet_institutions, total_in_use_toilet_institutions, total_in_use_improved_toilet_institutions, total_in_use_single_sex_toilet_institutions, total_improved_in_use_single_sex_toilet_institutions, total_drinking_water_institutions, total_functional_drinking_water_institutions, total_handwashing_facility_institutions, total_accessible_room_institutions) SELECT main_query.academic_period_id ,main_query.academic_period_name ,main_query.institution_sector_id ,main_query.institution_sector_name ,main_query.education_system_id ,main_query.education_system_name ,main_query.education_level_isced_id ,main_query.education_level_isced_name ,main_query.education_level_isced_level ,COUNT(DISTINCT(main_query.institution_id)) count_total_instiutions ,IFNULL(COUNT(DISTINCT(electricity_info.institution_id)),0) count_electricity_institutions ,IFNULL(COUNT(DISTINCT(computer_info.institution_id)),0) count_computer_institutions ,IFNULL(COUNT(DISTINCT(teaching_computer_info.institution_id)),0) count_teaching_computer_institutions ,IFNULL(COUNT(DISTINCT(internet_info.institution_id)),0) count_internet_institutions ,IFNULL(COUNT(DISTINCT(toilet_info.institution_id)),0) count_toilet_institutions ,IFNULL(COUNT(DISTINCT(improved_toilet_info.institution_id)),0) count_improved_toilet_institutions ,IFNULL(COUNT(DISTINCT(single_sex_toilet_info.institution_id)),0) count_single_sex_toilet_institutions ,IFNULL(COUNT(DISTINCT(single_sex_improved_toilet_info.institution_id)),0) count_improved_single_sex_toilet_institutions ,IFNULL(COUNT(DISTINCT(in_use_toilet_info.institution_id)),0) count_in_use_toilet_institutions ,IFNULL(COUNT(DISTINCT(in_use_improved_toilet_info.institution_id)),0) count_in_use_improved_toilet_institutions ,IFNULL(COUNT(DISTINCT(in_use_single_sex_toilet_info.institution_id)),0) count_in_use_single_sex_toilet_institutions ,IFNULL(COUNT(DISTINCT(improved_in_use_single_sex_toilet_info.institution_id)),0) count_improved_in_use_single_sex_toilet_institutions ,IFNULL(COUNT(DISTINCT(drinking_water_info.institution_id)),0) count_drinking_water_institutions ,IFNULL(COUNT(DISTINCT(available_drinking_water_info.institution_id)),0) count_functional_drinking_water_institutions ,IFNULL(COUNT(DISTINCT(handwashing_facility_info.institution_id)),0) count_handwashing_facility_institutions ,IFNULL(COUNT(DISTINCT(accessible_rooms_info.institution_id)),0) count_accessible_room_institutions FROM ( SELECT academic_periods.id academic_period_id ,academic_periods.name academic_period_name ,institution_sectors.id institution_sector_id ,institution_sectors.name institution_sector_name ,education_systems.id education_system_id ,education_systems.name education_system_name ,education_level_isced.id education_level_isced_id ,education_level_isced.name education_level_isced_name ,education_level_isced.isced_level education_level_isced_level ,institutions.id institution_id FROM institution_grades INNER JOIN institutions ON institutions.id = institution_grades.institution_id INNER JOIN institution_sectors ON institution_sectors.id = institutions.institution_sector_id INNER JOIN education_grades ON education_grades.id = institution_grades.education_grade_id INNER JOIN education_programmes ON education_programmes.id = education_grades.education_programme_id INNER JOIN education_cycles ON education_cycles.id = education_programmes.education_cycle_id INNER JOIN education_levels ON education_levels.id = education_cycles.education_level_id INNER JOIN education_level_isced ON education_level_isced.id = education_levels.education_level_isced_id INNER JOIN education_systems ON education_systems.id = education_levels.education_system_id INNER JOIN academic_periods ON academic_periods.id = education_systems.academic_period_id INNER JOIN ( SELECT academic_periods.id academic_period_id ,academic_periods.name academic_period_name ,institution_sectors.id institution_sector_id ,institution_sectors.name institution_sector_name ,education_systems.id education_system_id ,education_systems.name education_system_name ,education_level_isced.id education_level_isced_id ,education_level_isced.name education_level_isced_name ,MAX(education_level_isced.isced_level) education_level_isced_level ,institutions.id institution_id FROM institution_grades INNER JOIN institutions ON institutions.id = institution_grades.institution_id INNER JOIN institution_sectors ON institution_sectors.id = institutions.institution_sector_id INNER JOIN education_grades ON education_grades.id = institution_grades.education_grade_id INNER JOIN education_programmes ON education_programmes.id = education_grades.education_programme_id INNER JOIN education_cycles ON education_cycles.id = education_programmes.education_cycle_id INNER JOIN education_levels ON education_levels.id = education_cycles.education_level_id INNER JOIN education_level_isced ON education_level_isced.id = education_levels.education_level_isced_id INNER JOIN education_systems ON education_systems.id = education_levels.education_system_id INNER JOIN academic_periods ON academic_periods.id = education_systems.academic_period_id WHERE institutions.institution_status_id = 1 GROUP BY academic_periods.id ,institution_sectors.id ,institutions.id) max_isced_level ON max_isced_level.academic_period_id = academic_periods.id AND max_isced_level.institution_sector_id = institution_sectors.id AND max_isced_level.institution_id = institutions.id AND max_isced_level.education_level_isced_level = education_level_isced.isced_level WHERE institutions.institution_status_id = 1 GROUP BY academic_periods.id ,institution_sectors.id ,education_level_isced.id ,institutions.id ) main_query LEFT JOIN ( SELECT infrastructure_utility_electricities.academic_period_id ,infrastructure_utility_electricities.institution_id FROM infrastructure_utility_electricities GROUP BY infrastructure_utility_electricities.academic_period_id ,infrastructure_utility_electricities.institution_id ) electricity_info ON electricity_info.academic_period_id = main_query.academic_period_id AND electricity_info.institution_id = main_query.institution_id LEFT JOIN ( SELECT institution_assets.institution_id FROM institution_assets INNER JOIN asset_types ON asset_types.id = institution_assets.asset_type_id WHERE institution_assets.asset_status_id = 1 AND (asset_types.name LIKE \'%Computer%\' OR asset_types.name LIKE \'%Laptop%\') GROUP BY institution_assets.institution_id ) computer_info ON computer_info.institution_id = main_query.institution_id LEFT JOIN ( SELECT institution_assets.institution_id FROM institution_assets INNER JOIN asset_types ON asset_types.id = institution_assets.asset_type_id WHERE institution_assets.purpose = 1 AND institution_assets.asset_status_id = 1 AND (asset_types.name LIKE \'%Computer%\' OR asset_types.name LIKE \'%Laptop%\') GROUP BY institution_assets.institution_id ) teaching_computer_info ON teaching_computer_info.institution_id = main_query.institution_id LEFT JOIN ( SELECT infrastructure_utility_internets.academic_period_id ,infrastructure_utility_internets.institution_id FROM infrastructure_utility_internets GROUP BY infrastructure_utility_internets.academic_period_id ,infrastructure_utility_internets.institution_id ) internet_info ON internet_info.academic_period_id = main_query.academic_period_id AND internet_info.institution_id = main_query.institution_id LEFT JOIN ( SELECT infrastructure_wash_sanitations.academic_period_id ,infrastructure_wash_sanitations.institution_id FROM infrastructure_wash_sanitations GROUP BY infrastructure_wash_sanitations.academic_period_id ,infrastructure_wash_sanitations.institution_id ) toilet_info ON toilet_info.academic_period_id = main_query.academic_period_id AND toilet_info.institution_id = main_query.institution_id LEFT JOIN ( SELECT infrastructure_wash_sanitations.academic_period_id ,infrastructure_wash_sanitations.institution_id FROM infrastructure_wash_sanitations INNER JOIN infrastructure_wash_sanitation_qualities ON infrastructure_wash_sanitation_qualities.id = infrastructure_wash_sanitations.infrastructure_wash_sanitation_quality_id WHERE infrastructure_wash_sanitation_qualities.name LIKE \'%Improved%\' GROUP BY infrastructure_wash_sanitations.academic_period_id ,infrastructure_wash_sanitations.institution_id ) improved_toilet_info ON improved_toilet_info.academic_period_id = main_query.academic_period_id AND improved_toilet_info.institution_id = main_query.institution_id LEFT JOIN ( SELECT infrastructure_wash_sanitations.academic_period_id ,infrastructure_wash_sanitations.institution_id FROM infrastructure_wash_sanitations GROUP BY infrastructure_wash_sanitations.academic_period_id ,infrastructure_wash_sanitations.institution_id HAVING ( SUM(infrastructure_wash_sanitations.infrastructure_wash_sanitation_total_male) = 0 AND SUM(infrastructure_wash_sanitations.infrastructure_wash_sanitation_total_mixed) = 0 ) OR ( SUM(infrastructure_wash_sanitations.infrastructure_wash_sanitation_total_female) = 0 AND SUM(infrastructure_wash_sanitations.infrastructure_wash_sanitation_total_mixed) = 0 ) ) single_sex_toilet_info ON single_sex_toilet_info.academic_period_id = main_query.academic_period_id AND single_sex_toilet_info.institution_id = main_query.institution_id LEFT JOIN ( SELECT infrastructure_wash_sanitations.academic_period_id ,infrastructure_wash_sanitations.institution_id FROM infrastructure_wash_sanitations INNER JOIN infrastructure_wash_sanitation_qualities ON infrastructure_wash_sanitation_qualities.id = infrastructure_wash_sanitations.infrastructure_wash_sanitation_quality_id WHERE infrastructure_wash_sanitation_qualities.name LIKE \'%Improved%\' GROUP BY infrastructure_wash_sanitations.academic_period_id ,infrastructure_wash_sanitations.institution_id HAVING ( SUM(infrastructure_wash_sanitations.infrastructure_wash_sanitation_total_male) = 0 AND SUM(infrastructure_wash_sanitations.infrastructure_wash_sanitation_total_mixed) = 0 ) OR ( SUM(infrastructure_wash_sanitations.infrastructure_wash_sanitation_total_female) = 0 AND SUM(infrastructure_wash_sanitations.infrastructure_wash_sanitation_total_mixed) = 0 ) ) single_sex_improved_toilet_info ON single_sex_improved_toilet_info.academic_period_id = main_query.academic_period_id AND single_sex_improved_toilet_info.institution_id = main_query.institution_id LEFT JOIN ( SELECT infrastructure_wash_sanitations.academic_period_id ,infrastructure_wash_sanitations.institution_id FROM infrastructure_wash_sanitations INNER JOIN ( SELECT * FROM infrastructure_wash_sanitation_quantities WHERE infrastructure_wash_sanitation_quantities.functional = 1 GROUP BY infrastructure_wash_sanitation_quantities.infrastructure_wash_sanitation_id ,infrastructure_wash_sanitation_quantities.functional HAVING SUM(infrastructure_wash_sanitation_quantities.value) > 0 ) in_use_toilets ON in_use_toilets.infrastructure_wash_sanitation_id = infrastructure_wash_sanitations.id GROUP BY infrastructure_wash_sanitations.academic_period_id ,infrastructure_wash_sanitations.institution_id ) in_use_toilet_info ON in_use_toilet_info.academic_period_id = main_query.academic_period_id AND in_use_toilet_info.institution_id = main_query.institution_id LEFT JOIN ( SELECT infrastructure_wash_sanitations.academic_period_id ,infrastructure_wash_sanitations.institution_id FROM infrastructure_wash_sanitations INNER JOIN ( SELECT * FROM infrastructure_wash_sanitation_quantities WHERE infrastructure_wash_sanitation_quantities.functional = 1 GROUP BY infrastructure_wash_sanitation_quantities.infrastructure_wash_sanitation_id ,infrastructure_wash_sanitation_quantities.functional HAVING SUM(infrastructure_wash_sanitation_quantities.value) > 0 ) in_use_toilets ON in_use_toilets.infrastructure_wash_sanitation_id = infrastructure_wash_sanitations.id INNER JOIN infrastructure_wash_sanitation_qualities ON infrastructure_wash_sanitation_qualities.id = infrastructure_wash_sanitations.infrastructure_wash_sanitation_quality_id WHERE infrastructure_wash_sanitation_qualities.name LIKE \'%Improved%\' GROUP BY infrastructure_wash_sanitations.academic_period_id ,infrastructure_wash_sanitations.institution_id ) in_use_improved_toilet_info ON in_use_improved_toilet_info.academic_period_id = main_query.academic_period_id AND in_use_improved_toilet_info.institution_id = main_query.institution_id LEFT JOIN ( SELECT infrastructure_wash_sanitations.academic_period_id ,infrastructure_wash_sanitations.institution_id FROM infrastructure_wash_sanitations INNER JOIN ( SELECT * FROM infrastructure_wash_sanitation_quantities WHERE infrastructure_wash_sanitation_quantities.functional = 1 GROUP BY infrastructure_wash_sanitation_quantities.infrastructure_wash_sanitation_id ,infrastructure_wash_sanitation_quantities.functional HAVING SUM(infrastructure_wash_sanitation_quantities.value) > 0 ) in_use_toilets ON in_use_toilets.infrastructure_wash_sanitation_id = infrastructure_wash_sanitations.id GROUP BY infrastructure_wash_sanitations.academic_period_id ,infrastructure_wash_sanitations.institution_id HAVING ( SUM(infrastructure_wash_sanitations.infrastructure_wash_sanitation_total_male) = 0 AND SUM(infrastructure_wash_sanitations.infrastructure_wash_sanitation_total_mixed) = 0 ) OR ( SUM(infrastructure_wash_sanitations.infrastructure_wash_sanitation_total_female) = 0 AND SUM(infrastructure_wash_sanitations.infrastructure_wash_sanitation_total_mixed) = 0 ) ) in_use_single_sex_toilet_info ON in_use_single_sex_toilet_info.academic_period_id = main_query.academic_period_id AND in_use_single_sex_toilet_info.institution_id = main_query.institution_id LEFT JOIN ( SELECT infrastructure_wash_sanitations.academic_period_id ,infrastructure_wash_sanitations.institution_id FROM infrastructure_wash_sanitations INNER JOIN ( SELECT * FROM infrastructure_wash_sanitation_quantities WHERE infrastructure_wash_sanitation_quantities.functional = 1 GROUP BY infrastructure_wash_sanitation_quantities.infrastructure_wash_sanitation_id ,infrastructure_wash_sanitation_quantities.functional HAVING SUM(infrastructure_wash_sanitation_quantities.value) > 0 ) in_use_toilets ON in_use_toilets.infrastructure_wash_sanitation_id = infrastructure_wash_sanitations.id INNER JOIN infrastructure_wash_sanitation_qualities ON infrastructure_wash_sanitation_qualities.id = infrastructure_wash_sanitations.infrastructure_wash_sanitation_quality_id WHERE infrastructure_wash_sanitation_qualities.name LIKE \'%Improved%\' GROUP BY infrastructure_wash_sanitations.academic_period_id ,infrastructure_wash_sanitations.institution_id HAVING ( SUM(infrastructure_wash_sanitations.infrastructure_wash_sanitation_total_male) = 0 AND SUM(infrastructure_wash_sanitations.infrastructure_wash_sanitation_total_mixed) = 0 ) OR ( SUM(infrastructure_wash_sanitations.infrastructure_wash_sanitation_total_female) = 0 AND SUM(infrastructure_wash_sanitations.infrastructure_wash_sanitation_total_mixed) = 0 ) ) improved_in_use_single_sex_toilet_info ON improved_in_use_single_sex_toilet_info.academic_period_id = main_query.academic_period_id AND improved_in_use_single_sex_toilet_info.institution_id = main_query.institution_id LEFT JOIN ( SELECT infrastructure_wash_waters.academic_period_id ,infrastructure_wash_waters.institution_id FROM infrastructure_wash_waters GROUP BY infrastructure_wash_waters.academic_period_id ,infrastructure_wash_waters.institution_id ) drinking_water_info ON drinking_water_info.academic_period_id = main_query.academic_period_id AND drinking_water_info.institution_id = main_query.institution_id LEFT JOIN ( SELECT infrastructure_wash_waters.academic_period_id ,infrastructure_wash_waters.institution_id FROM infrastructure_wash_waters INNER JOIN infrastructure_wash_water_functionalities ON infrastructure_wash_water_functionalities.id = infrastructure_wash_waters.infrastructure_wash_water_functionality_id WHERE infrastructure_wash_water_functionalities.name NOT LIKE \'%Not Functional%\' GROUP BY infrastructure_wash_waters.academic_period_id ,infrastructure_wash_waters.institution_id ) available_drinking_water_info ON available_drinking_water_info.academic_period_id = main_query.academic_period_id AND available_drinking_water_info.institution_id = main_query.institution_id LEFT JOIN ( SELECT infrastructure_wash_hygienes.academic_period_id ,infrastructure_wash_hygienes.institution_id FROM infrastructure_wash_hygienes INNER JOIN infrastructure_wash_hygiene_types ON infrastructure_wash_hygiene_types.id = infrastructure_wash_hygienes.infrastructure_wash_hygiene_type_id WHERE infrastructure_wash_hygiene_types.name NOT LIKE \'%Not Available%\' GROUP BY infrastructure_wash_hygienes.academic_period_id ,infrastructure_wash_hygienes.institution_id ) handwashing_facility_info ON handwashing_facility_info.academic_period_id = main_query.academic_period_id AND handwashing_facility_info.institution_id = main_query.institution_id LEFT JOIN ( SELECT institution_rooms.academic_period_id ,institution_rooms.institution_id FROM institution_rooms WHERE institution_rooms.accessibility = 1 GROUP BY institution_rooms.academic_period_id ,institution_rooms.institution_id ) accessible_rooms_info ON accessible_rooms_info.academic_period_id = main_query.academic_period_id AND accessible_rooms_info.institution_id = main_query.institution_id GROUP BY main_query.academic_period_id ,main_query.institution_sector_id ,main_query.education_level_isced_id;', 'week', 1, NULL, NULL, 1, '2023-01-12 07:54:34'),
(51, 'summary_area_provider_grade_subject_results_create', 'CREATE TABLE IF NOT EXISTS `summary_area_provider_grade_subject_results`( `academic_period_id` int(11) NOT NULL ,`academic_period_name` varchar(200) NOT NULL ,`area_id` int(11) NOT NULL ,`area_code` varchar(200) NOT NULL ,`area_name` varchar(200) NOT NULL ,`institution_provider_id` int(11) NOT NULL ,`institution_provider_name` varchar(200) NOT NULL ,`education_grade_id` int(11) NOT NULL ,`education_grade_code` varchar(200) NOT NULL ,`education_grade_name` varchar(200) NOT NULL ,`education_subject_id` int(11) NOT NULL ,`education_subject_code` varchar(200) NOT NULL ,`education_subject_name` varchar(200) NOT NULL ,`total_avg_results` varchar(200) NULL ,`male_avg_results` varchar(200) NULL ,`female_avg_results` varchar(200) NULL ,`created` datetime NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8;', 'week', 1, NULL, NULL, 1, '2023-02-01 05:51:09'),
(52, 'summary_area_provider_grade_subject_results_truncate', 'TRUNCATE summary_area_provider_grade_subject_results;', 'week', 1, NULL, NULL, 1, '2023-02-01 05:51:09'),
(53, 'summary_area_provider_grade_subject_results_insert', 'INSERT INTO `summary_area_provider_grade_subject_results`(`academic_period_id`, `academic_period_name`, `area_id`, `area_code`, `area_name`, `institution_provider_id`, `institution_provider_name`, `education_grade_id`, `education_grade_code`, `education_grade_name`, `education_subject_id`, `education_subject_code`, `education_subject_name`, `total_avg_results`, `male_avg_results`, `female_avg_results`, `created`) SELECT subq.academic_period_id ,subq.academic_period_name ,subq.area_id ,subq.area_code ,subq.area_name ,subq.institution_provider_id ,subq.institution_provider_name ,subq.education_grade_id ,subq.education_grade_code ,subq.education_grade_name ,subq.education_subject_id ,subq.education_subject_code ,subq.education_subject_name ,ROUND(AVG(subq.all_total), 5) total_avg_results ,ROUND(AVG(subq.all_male), 5) male_avg_results ,ROUND(AVG(subq.all_female), 5) female_avg_results ,CURRENT_TIMESTAMP() created FROM ( SELECT areas.id area_id ,areas.code area_code ,areas.name area_name ,academic_periods.id academic_period_id ,academic_periods.name academic_period_name ,institution_providers.id institution_provider_id ,institution_providers.name institution_provider_name ,education_grades.id education_grade_id ,education_grades.code education_grade_code ,education_grades.name education_grade_name ,education_subjects.id education_subject_id ,education_subjects.code education_subject_code ,education_subjects.name education_subject_name ,SUM(assessment_item_results.marks * assessment_periods.weight) / IFNULL(assessment_grading_types.max, CEILING(MAX(assessment_item_results.marks) / 10) * 10) * 100 all_total ,CASE WHEN genders.id = 1 THEN SUM(assessment_item_results.marks * assessment_periods.weight) / IFNULL(assessment_grading_types.max, CEILING(MAX(assessment_item_results.marks) / 10) * 10) * 100 END all_male ,CASE WHEN genders.id = 2 THEN SUM(assessment_item_results.marks * assessment_periods.weight) / IFNULL(assessment_grading_types.max, CEILING(MAX(assessment_item_results.marks) / 10) * 10) * 100 END all_female FROM assessment_item_results INNER JOIN ( SELECT assessment_item_results.student_id ,assessment_item_results.assessment_id ,assessment_item_results.education_subject_id ,assessment_item_results.assessment_period_id ,MAX(assessment_item_results.created) latest_created FROM assessment_item_results GROUP BY assessment_item_results.student_id ,assessment_item_results.assessment_id ,assessment_item_results.education_subject_id ,assessment_item_results.assessment_period_id) latest_grades ON latest_grades.student_id = assessment_item_results.student_id AND latest_grades.assessment_id = assessment_item_results.assessment_id AND latest_grades.education_subject_id = assessment_item_results.education_subject_id AND latest_grades.assessment_period_id = assessment_item_results.assessment_period_id AND latest_grades.latest_created = assessment_item_results.created LEFT JOIN assessment_grading_options ON assessment_grading_options.id = assessment_item_results.assessment_grading_option_id LEFT JOIN assessment_grading_types ON assessment_grading_types.id = assessment_grading_options.assessment_grading_type_id INNER JOIN assessment_periods ON assessment_periods.id = assessment_item_results.assessment_period_id AND assessment_periods.assessment_id = assessment_item_results.assessment_id INNER JOIN academic_periods ON academic_periods.id = assessment_item_results.academic_period_id INNER JOIN institutions ON institutions.id = assessment_item_results.institution_id INNER JOIN institution_providers ON institution_providers.id = institutions.institution_provider_id INNER JOIN areas ON areas.id = institutions.area_id INNER JOIN security_users ON security_users.id = assessment_item_results.student_id INNER JOIN genders ON genders.id = security_users.gender_id INNER JOIN education_grades ON education_grades.id = assessment_item_results.education_grade_id INNER JOIN education_subjects ON education_subjects.id = assessment_item_results.education_subject_id GROUP BY education_subjects.id ,security_users.id ) subq GROUP BY subq.area_id ,subq.academic_period_id ,subq.institution_provider_id ,subq.education_grade_id ,subq.education_subject_id', 'week', 1, NULL, NULL, 1, '2023-02-01 05:51:09'),
(54, 'summary_institution_student_subject_results_create', 'CREATE TABLE IF NOT EXISTS `summary_institution_student_subject_results`( `academic_period_id` int(11) NOT NULL ,`academic_period_name` varchar(200) NOT NULL ,`area_id` int(11) NOT NULL ,`area_code` varchar(200) NOT NULL ,`area_name` varchar(200) NOT NULL ,`area_administrative_id` int(11) NULL ,`area_administrative_code` varchar(200) NULL ,`area_administrative_name` varchar(200) NULL ,`institution_provider_id` int(11) NOT NULL ,`institution_provider_name` varchar(200) NOT NULL ,`institution_ownership_id` int(11) NOT NULL ,`institution_ownership_name` varchar(200) NOT NULL ,`institution_gender_id` int(11) NOT NULL ,`institution_gender_name` varchar(200) NOT NULL ,`institution_id` int(11) NOT NULL ,`institution_code` varchar(200) NOT NULL ,`institution_name` varchar(200) NOT NULL ,`education_grade_id` int(11) NOT NULL ,`education_grade_code` varchar(200) NOT NULL ,`education_grade_name` varchar(200) NOT NULL ,`student_id` int(11) NOT NULL ,`student_openemis_no` varchar(200) NOT NULL ,`student_first_name` varchar(200) NOT NULL ,`student_middle_name` varchar(200) NULL ,`student_third_name` varchar(200) NULL ,`student_last_name` varchar(200) NOT NULL ,`student_gender_id` int(11) NOT NULL ,`student_gender_name` varchar(200) NOT NULL ,`student_default_identity_id` int(11) NULL ,`student_default_identity_type` varchar(200) NULL ,`student_default_identity_number` varchar(200) NULL ,`student_default_nationality_id` int(11) NULL ,`student_default_nationality_name` varchar(200) NULL ,`education_subject_id` int(11) NOT NULL ,`education_subject_code` varchar(200) NOT NULL ,`education_subject_name` varchar(200) NOT NULL ,`total_avg_results` varchar(200) NULL ,`male_avg_results` varchar(200) NULL ,`female_avg_results` varchar(200) NULL ,`created` datetime NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8;', 'week', 1, NULL, NULL, 1, '2023-02-08 08:22:38'),
(55, 'summary_institution_student_subject_results_truncate', 'TRUNCATE summary_institution_student_subject_results;', 'week', 1, NULL, NULL, 1, '2023-02-08 08:22:38');
INSERT INTO `report_queries` (`id`, `name`, `query_sql`, `frequency`, `status`, `modified_user_id`, `modified`, `created_user_id`, `created`) VALUES
(56, 'summary_institution_student_subject_results_insert', 'INSERT INTO `summary_institution_student_subject_results`(`academic_period_id`, `academic_period_name`, `area_id`, `area_code`, `area_name`, `area_administrative_id`, `area_administrative_code`, `area_administrative_name`, `institution_provider_id`, `institution_provider_name`, `institution_ownership_id`, `institution_ownership_name`, `institution_gender_id`, `institution_gender_name`, `institution_id`, `institution_code`, `institution_name`, `education_grade_id`, `education_grade_code`, `education_grade_name`, `student_id`, `student_openemis_no`, `student_first_name`, `student_middle_name`, `student_third_name`, `student_last_name`, `student_gender_id`, `student_gender_name`, `student_default_identity_id`, `student_default_identity_type`, `student_default_identity_number`, `student_default_nationality_id`, `student_default_nationality_name`, `education_subject_id`, `education_subject_code`, `education_subject_name`, `total_avg_results`, `male_avg_results`, `female_avg_results`, `created`) SELECT academic_periods.id academic_period_id ,academic_periods.name academic_period_name ,areas.id area_id ,areas.code area_code ,areas.name area_name ,area_administratives.id area_administrative_id ,area_administratives.code area_administrative_code ,area_administratives.name area_administrative_name ,institution_providers.id institution_provider_id ,institution_providers.name institution_provider_name ,institution_ownerships.id institution_ownership_id ,institution_ownerships.name institution_ownership_name ,institution_genders.id institution_gender_id ,institution_genders.name institution_gender_name ,institutions.id institution_id ,institutions.code institution_code ,institutions.name institution_name ,education_grades.id education_grade_id ,education_grades.code education_grade_code ,education_grades.name education_grade_name ,security_users.id student_id ,security_users.openemis_no student_openemis_no ,security_users.first_name student_first_name ,security_users.middle_name student_middle_name ,security_users.third_name student_third_name ,security_users.last_name student_last_name ,genders.id student_gender_id ,genders.name student_gender_name ,student_identities.student_default_identity_id ,student_identities.student_default_identity_type ,student_identities.student_default_identity_number ,student_nationalities.student_default_nationality_id ,student_nationalities.student_default_nationality_name ,education_subjects.id education_subject_id ,education_subjects.code education_subject_code ,education_subjects.name education_subject_name ,ROUND(SUM(assessment_item_results.marks * assessment_periods.weight) / IFNULL(assessment_grading_types.max, CEILING(MAX(assessment_item_results.marks) / 10) * 10) * 100, 5) total_avg_results ,CASE WHEN genders.id = 1 THEN ROUND(SUM(assessment_item_results.marks * assessment_periods.weight) / IFNULL(assessment_grading_types.max, CEILING(MAX(assessment_item_results.marks) / 10) * 10) * 100, 5) END male_avg_results ,CASE WHEN genders.id = 2 THEN ROUND(SUM(assessment_item_results.marks * assessment_periods.weight) / IFNULL(assessment_grading_types.max, CEILING(MAX(assessment_item_results.marks) / 10) * 10) * 100, 5) END female_avg_results ,CURRENT_TIMESTAMP() created FROM assessment_item_results INNER JOIN ( SELECT assessment_item_results.student_id ,assessment_item_results.assessment_id ,assessment_item_results.education_subject_id ,assessment_item_results.assessment_period_id ,MAX(assessment_item_results.created) latest_created FROM assessment_item_results GROUP BY assessment_item_results.student_id ,assessment_item_results.assessment_id ,assessment_item_results.education_subject_id ,assessment_item_results.assessment_period_id) latest_grades ON latest_grades.student_id = assessment_item_results.student_id AND latest_grades.assessment_id = assessment_item_results.assessment_id AND latest_grades.education_subject_id = assessment_item_results.education_subject_id AND latest_grades.assessment_period_id = assessment_item_results.assessment_period_id AND latest_grades.latest_created = assessment_item_results.created LEFT JOIN assessment_grading_options ON assessment_grading_options.id = assessment_item_results.assessment_grading_option_id LEFT JOIN assessment_grading_types ON assessment_grading_types.id = assessment_grading_options.assessment_grading_type_id INNER JOIN assessment_periods ON assessment_periods.id = assessment_item_results.assessment_period_id AND assessment_periods.assessment_id = assessment_item_results.assessment_id INNER JOIN academic_periods ON academic_periods.id = assessment_item_results.academic_period_id INNER JOIN institutions ON institutions.id = assessment_item_results.institution_id INNER JOIN institution_genders ON institution_genders.id = institutions.institution_gender_id INNER JOIN institution_ownerships ON institution_ownerships.id = institutions.institution_ownership_id INNER JOIN institution_providers ON institution_providers.id = institutions.institution_provider_id INNER JOIN areas ON areas.id = institutions.area_id LEFT JOIN area_administratives ON area_administratives.id = institutions.area_administrative_id INNER JOIN security_users ON security_users.id = assessment_item_results.student_id INNER JOIN genders ON genders.id = security_users.gender_id LEFT JOIN ( SELECT user_nationalities.id student_default_nationality_id ,user_nationalities.security_user_id ,nationalities.name student_default_nationality_name FROM user_nationalities INNER JOIN nationalities ON nationalities.id = user_nationalities.nationality_id WHERE user_nationalities.preferred = 1 GROUP BY user_nationalities.security_user_id ) AS student_nationalities ON student_nationalities.security_user_id = security_users.id LEFT JOIN ( SELECT user_identities.security_user_id ,GROUP_CONCAT(user_identities.id) student_default_identity_id ,GROUP_CONCAT(identity_types.name) student_default_identity_type ,GROUP_CONCAT(user_identities.number) student_default_identity_number FROM user_identities INNER JOIN identity_types ON identity_types.id = user_identities.identity_type_id WHERE identity_types.default = 1 GROUP BY user_identities.security_user_id ) AS student_identities ON student_identities.security_user_id = security_users.id INNER JOIN education_grades ON education_grades.id = assessment_item_results.education_grade_id INNER JOIN education_subjects ON education_subjects.id = assessment_item_results.education_subject_id GROUP BY education_subjects.id ,security_users.id;', 'week', 1, NULL, NULL, 1, '2023-02-08 08:22:38'),
(57, 'summary_area_institution_grade_attendances', 'INSERT INTO `summary_area_institution_grade_attendances`(`academic_period_id`, `academic_period_name`, `area_id`, `area_code`, `area_name`, `institution_id`, `institution_code`, `institution_name`, `education_grade_id`, `education_grade_code`, `education_grade_name`, `attendance_date`, `marked_classes` , `total_classes`, `female_count`, `male_count`, `total_count`, `present_female_count`, `present_male_count`, `present_total_count`, `absent_female_count`, `absent_male_count`, `absent_total_count`, `late_female_count`, `late_male_count`, `late_total_count`, `created`) SELECT academic_periods.id ,academic_periods.name ,areas.id ,areas.code ,areas.name ,institutions.id ,institutions.code ,institutions.name ,education_grades.id ,education_grades.code ,education_grades.name ,DATE(CONVERT_TZ(NOW(), @@session.time_zone, time_zone_info.value)) attendance_date ,0 ,COUNT(DISTINCT(institution_class_students.institution_class_id)) total_classes ,COUNT(DISTINCT(CASE WHEN security_users.gender_id = 1 THEN institution_class_students.student_id END)) male_count ,COUNT(DISTINCT(CASE WHEN security_users.gender_id = 2 THEN institution_class_students.student_id END)) female_count ,COUNT(DISTINCT(CASE WHEN security_users.gender_id = 1 THEN institution_class_students.student_id END)) + COUNT(DISTINCT(CASE WHEN security_users.gender_id = 2 THEN institution_class_students.student_id END)) total_students ,0 ,0 ,0 ,0 ,0 ,0 ,0 ,0 ,0 ,CONVERT_TZ(NOW(), @@session.time_zone, time_zone_info.value) created_at FROM institution_class_students INNER JOIN security_users ON security_users.id = institution_class_students.student_id INNER JOIN institutions ON institutions.id = institution_class_students.institution_id INNER JOIN areas ON areas.id = institutions.area_id INNER JOIN education_grades ON education_grades.id = institution_class_students.education_grade_id INNER JOIN academic_periods ON academic_periods.id = institution_class_students.academic_period_id INNER JOIN ( SELECT config_items.value FROM config_items WHERE config_items.code = \'time_zone\') time_zone_info WHERE academic_periods.current = 1 AND institution_class_students.student_status_id = 1 GROUP BY education_grades.id ,institutions.id ,academic_periods.id ,attendance_date ORDER BY institutions.id ASC;', 'day', 1, NULL, NULL, 1, '2023-03-08 08:29:34'),
(58, 'summary_institution_nationalities_create', 'CREATE TABLE IF NOT EXISTS `summary_institution_nationalities`( `academic_period_id` int(11) NOT NULL, `academic_period_name` varchar(50) NOT NULL, `institution_id` int(11) NOT NULL, `institution_code` varchar(50) NOT NULL, `nationality_id` int(11) NULL, `nationality_name` varchar(50) NULL, `total_students` int(9) NOT NULL, `total_students_female` int(9) NOT NULL, `total_students_male` int(9) NOT NULL) ENGINE = InnoDB DEFAULT CHARSET = utf8;', 'week', 1, NULL, NULL, 1, '2023-04-27 10:02:31'),
(59, 'summary_institution_nationalities_truncate', 'TRUNCATE summary_institution_nationalities;', 'week', 1, NULL, NULL, 1, '2023-04-27 10:02:31'),
(60, 'summary_institution_nationalities_insert', 'INSERT INTO summary_institution_nationalities (academic_period_id, academic_period_name, institution_id, institution_code, nationality_id, nationality_name, total_students, total_students_female, total_students_male) SELECT academic_periods.id academic_period_id ,academic_periods.name academic_period_name ,institutions.id institution_id ,institutions.code institution_code ,IFNULL(nationalities.id, 0) nationality_id ,nationalities.name nationality_name ,SUM(CASE WHEN security_users.gender_id IN (1,2) AND IF((CURRENT_DATE >= academic_periods.start_date AND CURRENT_DATE <= academic_periods.end_date), institution_students.student_status_id = 1, institution_students.student_status_id IN (1, 7, 6, 8)) THEN 1 ELSE 0 END) total_students ,SUM(CASE WHEN security_users.gender_id = 2 AND IF((CURRENT_DATE >= academic_periods.start_date AND CURRENT_DATE <= academic_periods.end_date), institution_students.student_status_id = 1, institution_students.student_status_id IN (1, 7, 6, 8)) THEN 1 ELSE 0 END) total_students_female ,SUM(CASE WHEN security_users.gender_id = 1 AND IF((CURRENT_DATE >= academic_periods.start_date AND CURRENT_DATE <= academic_periods.end_date), institution_students.student_status_id = 1, institution_students.student_status_id IN (1, 7, 6, 8)) THEN 1 ELSE 0 END) total_students_male FROM institution_students INNER JOIN security_users ON security_users.id = institution_students.student_id INNER JOIN institutions ON institutions.id = institution_students.institution_id INNER JOIN academic_periods ON academic_periods.id = institution_students.academic_period_id LEFT JOIN user_nationalities ON user_nationalities.security_user_id = security_users.id LEFT JOIN nationalities ON nationalities.id = user_nationalities.nationality_id GROUP BY institution_students.academic_period_id ,institution_students.institution_id ,nationalities.id;', 'week', 1, NULL, NULL, 1, '2023-04-27 10:02:31'),
(61, 'summary_institution_grade_nationalities_create', 'CREATE TABLE IF NOT EXISTS `summary_institution_grade_nationalities`( `academic_period_id` int(11) NOT NULL, `academic_period_name` varchar(50) NOT NULL, `institution_id` int(11) NOT NULL, `institution_code` varchar(50) NOT NULL, `grade_id` int(11) NOT NULL, `grade_name` varchar(50) NOT NULL, `nationality_id` int(11) NULL, `nationality_name` varchar(50) NULL, `total_students` int(9) NOT NULL, `total_students_female` int(9) NOT NULL, `total_students_male` int(9) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8;', 'week', 1, NULL, NULL, 1, '2023-04-27 10:02:31'),
(62, 'summary_institution_grade_nationalities_truncate', 'TRUNCATE summary_institution_grade_nationalities;', 'week', 1, NULL, NULL, 1, '2023-04-27 10:02:31'),
(63, 'summary_institution_grade_nationalities_insert', 'INSERT INTO summary_institution_grade_nationalities(academic_period_id, academic_period_name, institution_id, institution_code, grade_id, grade_name, nationality_id, nationality_name, total_students, total_students_female, total_students_male) SELECT academic_periods.id academic_period_id ,academic_periods.name academic_period_name ,institutions.id institution_id ,institutions.code institution_code ,education_grades.id grade_id ,education_grades.name grade_name ,IFNULL(nationalities.id, 0) nationality_id ,nationalities.name nationality_name ,SUM(CASE WHEN security_users.gender_id IN (1,2) AND IF((CURRENT_DATE >= academic_periods.start_date AND CURRENT_DATE <= academic_periods.end_date), institution_students.student_status_id = 1, institution_students.student_status_id IN (1, 7, 6, 8)) THEN 1 ELSE 0 END) total_students ,SUM(CASE WHEN security_users.gender_id = 2 AND IF((CURRENT_DATE >= academic_periods.start_date AND CURRENT_DATE <= academic_periods.end_date), institution_students.student_status_id = 1, institution_students.student_status_id IN (1, 7, 6, 8)) THEN 1 ELSE 0 END) total_students_female ,SUM(CASE WHEN security_users.gender_id = 1 AND IF((CURRENT_DATE >= academic_periods.start_date AND CURRENT_DATE <= academic_periods.end_date), institution_students.student_status_id = 1, institution_students.student_status_id IN (1, 7, 6, 8)) THEN 1 ELSE 0 END) total_students_male FROM institution_students INNER JOIN security_users ON security_users.id = institution_students.student_id INNER JOIN education_grades ON education_grades.id = institution_students.education_grade_id INNER JOIN institutions ON institutions.id = institution_students.institution_id INNER JOIN academic_periods ON academic_periods.id = institution_students.academic_period_id LEFT JOIN user_nationalities ON user_nationalities.security_user_id = security_users.id LEFT JOIN nationalities ON nationalities.id = user_nationalities.nationality_id GROUP BY institution_students.academic_period_id ,institution_students.institution_id ,education_grades.id ,nationalities.id;', 'week', 1, NULL, NULL, 1, '2023-04-27 10:02:31'),
(64, 'summary_isced_sectors_insert', 'INSERT INTO summary_isced_sectors(academic_period_id, academic_period_name, institution_sector_id, institution_sector_name, education_system_id, education_system_name, education_level_isced_id, education_level_isced_name, education_level_isced_level, total_instiutions, total_electricity_institutions, total_computer_institutions, total_teaching_computer_institutions, total_internet_institutions, total_toilet_institutions, total_improved_toilet_institutions, total_single_sex_toilet_institutions, total_improved_single_sex_toilet_institutions, total_in_use_toilet_institutions, total_in_use_improved_toilet_institutions, total_in_use_single_sex_toilet_institutions, total_improved_in_use_single_sex_toilet_institutions, total_drinking_water_institutions, total_functional_drinking_water_institutions, total_handwashing_facility_institutions, total_accessible_room_institutions) SELECT main_query.academic_period_id ,main_query.academic_period_name ,main_query.institution_sector_id ,main_query.institution_sector_name ,main_query.education_system_id ,main_query.education_system_name ,main_query.education_level_isced_id ,main_query.education_level_isced_name ,main_query.education_level_isced_level ,COUNT(DISTINCT(main_query.institution_id)) count_total_instiutions ,IFNULL(COUNT(DISTINCT(electricity_info.institution_id)),0) count_electricity_institutions ,IFNULL(COUNT(DISTINCT(computer_info.institution_id)),0) count_computer_institutions ,IFNULL(COUNT(DISTINCT(teaching_computer_info.institution_id)),0) count_teaching_computer_institutions ,IFNULL(COUNT(DISTINCT(internet_info.institution_id)),0) count_internet_institutions ,IFNULL(COUNT(DISTINCT(toilet_info.institution_id)),0) count_toilet_institutions ,IFNULL(COUNT(DISTINCT(improved_toilet_info.institution_id)),0) count_improved_toilet_institutions ,IFNULL(COUNT(DISTINCT(single_sex_toilet_info.institution_id)),0) count_single_sex_toilet_institutions ,IFNULL(COUNT(DISTINCT(single_sex_improved_toilet_info.institution_id)),0) count_improved_single_sex_toilet_institutions ,IFNULL(COUNT(DISTINCT(in_use_toilet_info.institution_id)),0) count_in_use_toilet_institutions ,IFNULL(COUNT(DISTINCT(in_use_improved_toilet_info.institution_id)),0) count_in_use_improved_toilet_institutions ,IFNULL(COUNT(DISTINCT(in_use_single_sex_toilet_info.institution_id)),0) count_in_use_single_sex_toilet_institutions ,IFNULL(COUNT(DISTINCT(improved_in_use_single_sex_toilet_info.institution_id)),0) count_improved_in_use_single_sex_toilet_institutions ,IFNULL(COUNT(DISTINCT(drinking_water_info.institution_id)),0) count_drinking_water_institutions ,IFNULL(COUNT(DISTINCT(available_drinking_water_info.institution_id)),0) count_functional_drinking_water_institutions ,IFNULL(COUNT(DISTINCT(handwashing_facility_info.institution_id)),0) count_handwashing_facility_institutions ,IFNULL(COUNT(DISTINCT(accessible_rooms_info.institution_id)),0) count_accessible_room_institutions FROM ( SELECT academic_periods.id academic_period_id ,academic_periods.name academic_period_name ,institution_sectors.id institution_sector_id ,institution_sectors.name institution_sector_name ,education_systems.id education_system_id ,education_systems.name education_system_name ,education_level_isced.id education_level_isced_id ,education_level_isced.name education_level_isced_name ,education_level_isced.isced_level education_level_isced_level ,institutions.id institution_id FROM institution_grades INNER JOIN institutions ON institutions.id = institution_grades.institution_id INNER JOIN institution_sectors ON institution_sectors.id = institutions.institution_sector_id INNER JOIN education_grades ON education_grades.id = institution_grades.education_grade_id INNER JOIN education_programmes ON education_programmes.id = education_grades.education_programme_id INNER JOIN education_cycles ON education_cycles.id = education_programmes.education_cycle_id INNER JOIN education_levels ON education_levels.id = education_cycles.education_level_id INNER JOIN education_level_isced ON education_level_isced.id = education_levels.education_level_isced_id INNER JOIN education_systems ON education_systems.id = education_levels.education_system_id INNER JOIN academic_periods ON academic_periods.id = education_systems.academic_period_id INNER JOIN ( SELECT academic_periods.id academic_period_id ,academic_periods.name academic_period_name ,institution_sectors.id institution_sector_id ,institution_sectors.name institution_sector_name ,education_systems.id education_system_id ,education_systems.name education_system_name ,education_level_isced.id education_level_isced_id ,education_level_isced.name education_level_isced_name ,MAX(education_level_isced.isced_level) education_level_isced_level ,institutions.id institution_id FROM institution_grades INNER JOIN institutions ON institutions.id = institution_grades.institution_id INNER JOIN institution_sectors ON institution_sectors.id = institutions.institution_sector_id INNER JOIN education_grades ON education_grades.id = institution_grades.education_grade_id INNER JOIN education_programmes ON education_programmes.id = education_grades.education_programme_id INNER JOIN education_cycles ON education_cycles.id = education_programmes.education_cycle_id INNER JOIN education_levels ON education_levels.id = education_cycles.education_level_id INNER JOIN education_level_isced ON education_level_isced.id = education_levels.education_level_isced_id INNER JOIN education_systems ON education_systems.id = education_levels.education_system_id INNER JOIN academic_periods ON academic_periods.id = education_systems.academic_period_id WHERE institutions.institution_status_id = 1 GROUP BY academic_periods.id ,institution_sectors.id ,institutions.id) max_isced_level ON max_isced_level.academic_period_id = academic_periods.id AND max_isced_level.institution_sector_id = institution_sectors.id AND max_isced_level.institution_id = institutions.id AND max_isced_level.education_level_isced_level = education_level_isced.isced_level WHERE institutions.institution_status_id = 1 GROUP BY academic_periods.id ,institution_sectors.id ,education_level_isced.id ,institutions.id ) main_query LEFT JOIN ( SELECT infrastructure_utility_electricities.academic_period_id ,infrastructure_utility_electricities.institution_id FROM infrastructure_utility_electricities GROUP BY infrastructure_utility_electricities.academic_period_id ,infrastructure_utility_electricities.institution_id ) electricity_info ON electricity_info.academic_period_id = main_query.academic_period_id AND electricity_info.institution_id = main_query.institution_id LEFT JOIN ( SELECT institution_assets.institution_id FROM institution_assets INNER JOIN asset_types ON asset_types.id = institution_assets.asset_type_id WHERE institution_assets.asset_status_id = 1 AND (asset_types.name LIKE \'%Computer%\' OR asset_types.name LIKE \'%Laptop%\') GROUP BY institution_assets.institution_id ) computer_info ON computer_info.institution_id = main_query.institution_id LEFT JOIN ( SELECT institution_assets.institution_id FROM institution_assets INNER JOIN asset_types ON asset_types.id = institution_assets.asset_type_id WHERE institution_assets.purpose = 1 AND institution_assets.asset_status_id = 1 AND (asset_types.name LIKE \'%Computer%\' OR asset_types.name LIKE \'%Laptop%\') GROUP BY institution_assets.institution_id ) teaching_computer_info ON teaching_computer_info.institution_id = main_query.institution_id LEFT JOIN ( SELECT infrastructure_utility_internets.academic_period_id ,infrastructure_utility_internets.institution_id FROM infrastructure_utility_internets GROUP BY infrastructure_utility_internets.academic_period_id ,infrastructure_utility_internets.institution_id ) internet_info ON internet_info.academic_period_id = main_query.academic_period_id AND internet_info.institution_id = main_query.institution_id LEFT JOIN ( SELECT infrastructure_wash_sanitations.academic_period_id ,infrastructure_wash_sani