ture_wash_sanitation_qualities.id = infrastructure_wash_sanitations.infrastructure_wash_sanitation_quality_id WHERE infrastructure_wash_sanitation_qualities.name LIKE \'%Improved%\' GROUP BY infrastructure_wash_sanitations.academic_period_id ,infrastructure_wash_sanitations.institution_id HAVING ( SUM(infrastructure_wash_sanitations.infrastructure_wash_sanitation_total_male) = 0 AND SUM(infrastructure_wash_sanitations.infrastructure_wash_sanitation_total_mixed) = 0 ) OR ( SUM(infrastructure_wash_sanitations.infrastructure_wash_sanitation_total_female) = 0 AND SUM(infrastructure_wash_sanitations.infrastructure_wash_sanitation_total_mixed) = 0 ) ) single_sex_improved_toilet_info ON single_sex_improved_toilet_info.academic_period_id = main_query.academic_period_id AND single_sex_improved_toilet_info.institution_id = main_query.institution_id LEFT JOIN ( SELECT infrastructure_wash_sanitations.academic_period_id ,infrastructure_wash_sanitations.institution_id FROM infrastructure_wash_sanitations INNER JOIN ( SELECT * FROM infrastructure_wash_sanitation_quantities WHERE infrastructure_wash_sanitation_quantities.functional = 1 GROUP BY infrastructure_wash_sanitation_quantities.infrastructure_wash_sanitation_id ,infrastructure_wash_sanitation_quantities.functional HAVING SUM(infrastructure_wash_sanitation_quantities.value) > 0 ) in_use_toilets ON in_use_toilets.infrastructure_wash_sanitation_id = infrastructure_wash_sanitations.id GROUP BY infrastructure_wash_sanitations.academic_period_id ,infrastructure_wash_sanitations.institution_id ) in_use_toilet_info ON in_use_toilet_info.academic_period_id = main_query.academic_period_id AND in_use_toilet_info.institution_id = main_query.institution_id LEFT JOIN ( SELECT infrastructure_wash_sanitations.academic_period_id ,infrastructure_wash_sanitations.institution_id FROM infrastructure_wash_sanitations INNER JOIN ( SELECT * FROM infrastructure_wash_sanitation_quantities WHERE infrastructure_wash_sanitation_quantities.functional = 1 GROUP BY infrastructure_wash_sanitation_quantities.infrastructure_wash_sanitation_id ,infrastructure_wash_sanitation_quantities.functional HAVING SUM(infrastructure_wash_sanitation_quantities.value) > 0 ) in_use_toilets ON in_use_toilets.infrastructure_wash_sanitation_id = infrastructure_wash_sanitations.id INNER JOIN infrastructure_wash_sanitation_qualities ON infrastructure_wash_sanitation_qualities.id = infrastructure_wash_sanitations.infrastructure_wash_sanitation_quality_id WHERE infrastructure_wash_sanitation_qualities.name LIKE \'%Improved%\' GROUP BY infrastructure_wash_sanitations.academic_period_id ,infrastructure_wash_sanitations.institution_id ) in_use_improved_toilet_info ON in_use_improved_toilet_info.academic_period_id = main_query.academic_period_id AND in_use_improved_toilet_info.institution_id = main_query.institution_id LEFT JOIN ( SELECT infrastructure_wash_sanitations.academic_period_id ,infrastructure_wash_sanitations.institution_id FROM infrastructure_wash_sanitations INNER JOIN ( SELECT * FROM infrastructure_wash_sanitation_quantities WHERE infrastructure_wash_sanitation_quantities.functional = 1 GROUP BY infrastructure_wash_sanitation_quantities.infrastructure_wash_sanitation_id ,infrastructure_wash_sanitation_quantities.functional HAVING SUM(infrastructure_wash_sanitation_quantities.value) > 0 ) in_use_toilets ON in_use_toilets.infrastructure_wash_sanitation_id = infrastructure_wash_sanitations.id GROUP BY infrastructure_wash_sanitations.academic_period_id ,infrastructure_wash_sanitations.institution_id HAVING ( SUM(infrastructure_wash_sanitations.infrastructure_wash_sanitation_total_male) = 0 AND SUM(infrastructure_wash_sanitations.infrastructure_wash_sanitation_total_mixed) = 0 ) OR ( SUM(infrastructure_wash_sanitations.infrastructure_wash_sanitation_total_female) = 0 AND SUM(infrastructure_wash_sanitations.infrastructure_wash_sanitation_total_mixed) = 0 ) ) in_use_single_sex_toilet_info ON in_use_single_sex_toilet_info.academic_period_id = main_query.academic_period_id AND in_use_single_sex_toilet_info.institution_id = main_query.institution_id LEFT JOIN ( SELECT infrastructure_wash_sanitations.academic_period_id ,infrastructure_wash_sanitations.institution_id FROM infrastructure_wash_sanitations INNER JOIN ( SELECT * FROM infrastructure_wash_sanitation_quantities WHERE infrastructure_wash_sanitation_quantities.functional = 1 GROUP BY infrastructure_wash_sanitation_quantities.infrastructure_wash_sanitation_id ,infrastructure_wash_sanitation_quantities.functional HAVING SUM(infrastructure_wash_sanitation_quantities.value) > 0 ) in_use_toilets ON in_use_toilets.infrastructure_wash_sanitation_id = infrastructure_wash_sanitations.id INNER JOIN infrastructure_wash_sanitation_qualities ON infrastructure_wash_sanitation_qualities.id = infrastructure_wash_sanitations.infrastructure_wash_sanitation_quality_id WHERE infrastructure_wash_sanitation_qualities.name LIKE \'%Improved%\' GROUP BY infrastructure_wash_sanitations.academic_period_id ,infrastructure_wash_sanitations.institution_id HAVING ( SUM(infrastructure_wash_sanitations.infrastructure_wash_sanitation_total_male) = 0 AND SUM(infrastructure_wash_sanitations.infrastructure_wash_sanitation_total_mixed) = 0 ) OR ( SUM(infrastructure_wash_sanitations.infrastructure_wash_sanitation_total_female) = 0 AND SUM(infrastructure_wash_sanitations.infrastructure_wash_sanitation_total_mixed) = 0 ) ) improved_in_use_single_sex_toilet_info ON improved_in_use_single_sex_toilet_info.academic_period_id = main_query.academic_period_id AND improved_in_use_single_sex_toilet_info.institution_id = main_query.institution_id LEFT JOIN ( SELECT infrastructure_wash_waters.academic_period_id ,infrastructure_wash_waters.institution_id FROM infrastructure_wash_waters GROUP BY infrastructure_wash_waters.academic_period_id ,infrastructure_wash_waters.institution_id ) drinking_water_info ON drinking_water_info.academic_period_id = main_query.academic_period_id AND drinking_water_info.institution_id = main_query.institution_id LEFT JOIN ( SELECT infrastructure_wash_waters.academic_period_id ,infrastructure_wash_waters.institution_id FROM infrastructure_wash_waters INNER JOIN infrastructure_wash_water_functionalities ON infrastructure_wash_water_functionalities.id = infrastructure_wash_waters.infrastructure_wash_water_functionality_id WHERE infrastructure_wash_water_functionalities.name NOT LIKE \'%Not Functional%\' GROUP BY infrastructure_wash_waters.academic_period_id ,infrastructure_wash_waters.institution_id ) available_drinking_water_info ON available_drinking_water_info.academic_period_id = main_query.academic_period_id AND available_drinking_water_info.institution_id = main_query.institution_id LEFT JOIN ( SELECT infrastructure_wash_hygienes.academic_period_id ,infrastructure_wash_hygienes.institution_id FROM infrastructure_wash_hygienes INNER JOIN infrastructure_wash_hygiene_types ON infrastructure_wash_hygiene_types.id = infrastructure_wash_hygienes.infrastructure_wash_hygiene_type_id WHERE infrastructure_wash_hygiene_types.name NOT LIKE \'%Not Available%\' GROUP BY infrastructure_wash_hygienes.academic_period_id ,infrastructure_wash_hygienes.institution_id ) handwashing_facility_info ON handwashing_facility_info.academic_period_id = main_query.academic_period_id AND handwashing_facility_info.institution_id = main_query.institution_id LEFT JOIN ( SELECT institution_rooms.academic_period_id ,institution_rooms.institution_id FROM institution_rooms WHERE institution_rooms.accessibility = 1 GROUP BY institution_rooms.academic_period_id ,institution_rooms.institution_id ) accessible_rooms_info ON accessible_rooms_info.academic_period_id = main_query.academic_period_id AND accessible_rooms_info.institution_id = main_query.institution_id GROUP BY main_query.academic_period_id ,main_query.institution_sector_id ,main_query.education_level_isced_id;', 'week', 1, NULL, NULL, 1, '2023-04-27 10:02:31'),
