INSERT INTO `report_queries` (`id`, `name`, `query_sql`, `frequency`, `status`, `modified_user_id`, `modified`, `created_user_id`, `created`) VALUES
(66, 'summary_student_attendances_insert', 'INSERT IGNORE INTO summary_student_attendances SELECT main_query.academic_period_id ,main_query.academic_period_name ,main_query.institution_id ,main_query.institution_code ,main_query.institution_name ,main_query.education_grade_id ,main_query.education_grade_code ,main_query.education_grade_name ,main_query.institution_class_id ,main_query.institution_class_name ,dates_generator.date_info attendance_date ,attendance_marking_type.period_id ,attendance_marking_type.period_name ,attendance_marking_type.subject_id ,attendance_marking_type.subject_name ,main_query.total_female_count female_count ,main_query.total_male_count male_count ,main_query.total_male_count + main_query.total_female_count total_count ,CASE WHEN IF(marked_attendance.institution_id IS NOT NULL, IFNULL(marked_attendance.present_female_count, 0) + IFNULL(marked_attendance.present_male_count, 0), 0) < 0 THEN 0 ELSE IF(marked_attendance.institution_id IS NOT NULL, IFNULL(marked_attendance.present_female_count, 0) + IFNULL(marked_attendance.present_male_count, 0), 0) END marked_attendance ,IF(marked_attendance.institution_id IS NULL, main_query.total_male_count + main_query.total_female_count, 0) unmarked_attendance ,CASE WHEN IFNULL(marked_attendance.present_female_count, 0) - IFNULL(marked_absence.absent_female_count, 0) < 0 THEN 0 ELSE IFNULL(marked_attendance.present_female_count, 0) - IFNULL(marked_absence.absent_female_count, 0) END present_female_count ,CASE WHEN IFNULL(marked_attendance.present_male_count, 0) - IFNULL(marked_absence.absent_male_count, 0) < 0 THEN 0 ELSE IFNULL(marked_attendance.present_male_count, 0) - IFNULL(marked_absence.absent_male_count, 0) END present_male_count ,CASE WHEN IFNULL(marked_attendance.present_female_count, 0) + IFNULL(marked_attendance.present_male_count, 0) - (IFNULL(marked_absence.absent_female_count, 0) + IFNULL(marked_absence.absent_male_count, 0)) < 0 THEN 0 ELSE IFNULL(marked_attendance.present_female_count, 0) + IFNULL(marked_attendance.present_male_count, 0) - (IFNULL(marked_absence.absent_female_count, 0) + IFNULL(marked_absence.absent_male_count, 0)) END present_total_count ,CASE WHEN IFNULL(marked_absence.absent_female_count, 0) < 0 THEN 0 ELSE IFNULL(marked_absence.absent_female_count, 0) END absent_female_count ,CASE WHEN IFNULL(marked_absence.absent_male_count, 0) < 0 THEN 0 ELSE IFNULL(marked_absence.absent_male_count, 0) END absent_male_count ,CASE WHEN IFNULL(marked_absence.absent_female_count, 0) + IFNULL(marked_absence.absent_male_count, 0) < 0 THEN 0 ELSE IFNULL(marked_absence.absent_female_count, 0) + IFNULL(marked_absence.absent_male_count, 0) END absent_total_count ,CASE WHEN IFNULL(marked_absence.late_female_count, 0) < 0 THEN 0 ELSE IFNULL(marked_absence.late_female_count, 0) END late_female_count ,CASE WHEN IFNULL(marked_absence.late_male_count, 0) < 0 THEN 0 ELSE IFNULL(marked_absence.late_male_count, 0) END late_male_count ,CASE WHEN IFNULL(marked_absence.late_female_count, 0) + IFNULL(marked_absence.late_male_count, 0) < 0 THEN 0 ELSE IFNULL(marked_absence.late_female_count, 0) + IFNULL(marked_absence.late_male_count, 0) END late_total_count ,CURRENT_TIMESTAMP FROM ( SELECT institution_class_students.academic_period_id ,academic_periods.name academic_period_name ,academic_periods.start_date ,academic_periods.end_date ,institution_class_students.institution_id ,institutions.code institution_code ,institutions.name institution_name ,institution_class_students.education_grade_id ,education_grades.code education_grade_code ,education_grades.name education_grade_name ,institution_class_students.institution_class_id ,institution_classes.name institution_class_name ,COUNT(DISTINCT(CASE WHEN security_users.gender_id = 1 THEN institution_class_students.student_id END)) total_male_count ,COUNT(DISTINCT(CASE WHEN security_users.gender_id = 2 THEN institution_class_students.student_id END)) total_female_count FROM institution_class_students INNER JOIN security_users ON security_users.id = institution_class_students.student_id INNER JOIN institution_classes ON institution_classes.id = institution_class_students.institution_class_id INNER JOIN education_grades ON education_grades.id = institution_class_students.education_grade_id INNER JOIN institutions ON institutions.id = institution_class_students.institution_id INNER JOIN academic_periods ON academic_periods.id = institution_class_students.academic_period_id WHERE IF((CURRENT_DATE >= academic_periods.start_date AND CURRENT_DATE <= academic_periods.end_date), institution_class_students.student_status_id = 1, institution_class_students.student_status_id IN (1, 7, 6, 8)) GROUP BY institution_class_students.education_grade_id ,institution_class_students.institution_id ,institution_class_students.academic_period_id ,institution_class_students.institution_class_id ) main_query INNER JOIN ( SELECT institutions.id institution_id ,month_generator.date_info ,month_generator.start_date ,YEAR(month_generator.date_info) year_info FROM institutions INNER JOIN ( SELECT YEAR(m1) AS year_name ,MONTH(m1) AS month_id ,MONTHNAME(m1) AS month_name ,generated_date AS date_info ,start_date FROM ( SELECT dates_boundaries.start_date ,(dates_boundaries.start_date - INTERVAL DAYOFMONTH(dates_boundaries.start_date)-1 DAY) +INTERVAL m MONTH AS m1 ,dates_boundaries.end_date ,DATE((dates_boundaries.start_date - INTERVAL DAYOFMONTH(dates_boundaries.start_date)-1 DAY) +INTERVAL m MONTH + INTERVAL days.day DAY) AS generated_date FROM ( SELECT MIN(student_attendance_marked_records.date) start_date ,CURRENT_DATE end_date FROM student_attendance_marked_records ) dates_boundaries CROSS JOIN ( SELECT @rownum:= @rownum+1 AS m FROM ( SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 ) t1, ( SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 ) t2, ( SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 ) t3, ( SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 ) t4, ( SELECT @rownum:= -1 ) t0 ) d1 CROSS JOIN ( SELECT 0 AS day UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9 UNION ALL SELECT 10 UNION ALL SELECT 11 UNION ALL SELECT 12 UNION ALL SELECT 13 UNION ALL SELECT 14 UNION ALL SELECT 15 UNION ALL SELECT 16 UNION ALL SELECT 17 UNION ALL SELECT 18 UNION ALL SELECT 19 UNION ALL SELECT 20 UNION ALL SELECT 21 UNION ALL SELECT 22 UNION ALL SELECT 23 UNION ALL SELECT 24 UNION ALL SELECT 25 UNION ALL SELECT 26 UNION ALL SELECT 27 UNION ALL SELECT 28 UNION ALL SELECT 29 UNION ALL SELECT 30 ) AS days CROSS JOIN ( SELECT MAX(CASE WHEN config_items.code = \'first_day_of_week\' THEN IF(LENGTH(config_items.value) = 0, config_items.default_value, config_items.value) END) first_day_of_week ,MAX(CASE WHEN config_items.code = \'days_per_week\' THEN IF(LENGTH(config_items.value) = 0, config_items.default_value, config_items.value) END) days_per_week FROM config_items ) working_days LEFT JOIN ( SELECT calendar_event_dates.date public_hol FROM calendar_event_dates INNER JOIN calendar_events ON calendar_events.id = calendar_event_dates.calendar_event_id WHERE calendar_events.institution_id = -1 GROUP BY calendar_event_dates.date ) public_hol_info ON public_hol_info.public_hol = DATE((dates_boundaries.start_date - INTERVAL DAYOFMONTH(dates_boundaries.start_date)-1 DAY) +INTERVAL m MONTH + INTERVAL days.day DAY) WHERE DATE((dates_boundaries.start_date - INTERVAL DAYOFMONTH(dates_boundaries.start_date)-1 DAY) +INTERVAL m MONTH + INTERVAL days.day DAY) <= dates_boundaries.end_date AND MONTH(DATE((dates_boundaries.start_date - INTERVAL DAYOFMONTH(dates_boundaries.start_date)-1 DAY) +INTERVAL m MONTH + INTERVAL days.day DAY)) = MONTH((dates_boundaries.start_date - INTERVAL DAYOFMONTH(dates_boundaries.start_date)-1 DAY) +INTERVAL m MONTH) AND YEAR(DATE((dates_boundaries.start_date - INTERVAL DAYOFMONTH(dates_boundaries.start_date)-1 DAY) +INTERVAL m MONTH + INTERVAL