CREATE TABLE `system_processes` (
  `id` int NOT NULL,
  `name` varchar(50) NOT NULL,
  `process_id` int DEFAULT NULL,
  `callable_event` varchar(50) DEFAULT NULL,
  `status` int NOT NULL COMMENT '1 => New\n2 => Running\n3 => Completed\n-1 => Abort\n-2 => Error',
  `executed_count` int NOT NULL DEFAULT '0',
  `start_date` datetime DEFAULT NULL,
  `end_date` datetime DEFAULT NULL,
  `model` varchar(100) DEFAULT NULL,
  `params` text,
  `modified_user_id` int DEFAULT NULL,
  `modified` datetime DEFAULT NULL,
  `created_user_id` int NOT NULL,
  `created` datetime NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='Internal use - to track the background processes triggered by the system';

